import { db } from "@purplefish-ai/db/server";

import { inngest } from "@/server/inngest/client";
import {
  createInboundDispatchRule,
  createInboundTrunk,
  deleteInboundDispatchRule,
  deleteInboundTrunk,
} from "@/server/libs/agent-phone-numbers";

export const recreateInboundTrunksAndDispatchRules = inngest.createFunction(
  { id: "recreate-inbound-trunks-and-dispatch-rules" },
  { event: "migrations/inbound_trunks_and_dispatch_rules.recreate.triggered" },
  async ({ step, event }) => {
    await step.run("recreate-inbound-trunks-and-dispatch-rules", async () => {
      const { agentPhoneNumberIds } = event.data;
      const agentPhoneNumbers = agentPhoneNumberIds
        ? await db.agentPhoneNumber.findMany({
            where: { id: { in: agentPhoneNumberIds } },
          })
        : await db.agentPhoneNumber.findMany();

      for (let agentPhoneNumber of agentPhoneNumbers) {
        console.log(
          `Recreating rules for agent phone number ${agentPhoneNumber.id}`,
        );
        const inboundTrunkId = agentPhoneNumber.sipInboundTrunkId;
        if (!inboundTrunkId) {
          console.log(
            `Agent phone number ${agentPhoneNumber.id} has no inbound trunk`,
          );
          continue;
        }
        const dispatchRuleId = agentPhoneNumber.sipInboundDispatchRuleId;
        if (!dispatchRuleId) {
          console.log(
            `Agent phone number ${agentPhoneNumber.id} has no inbound dispatch rule`,
          );
          continue;
        }

        // Delete and recreate the inbound trunk and dispatch rule.
        try {
          await deleteInboundTrunk(agentPhoneNumber.id);
        } catch (error) {
          // Ignore "Not Found" errors since the trunk might not exist
          if (
            error instanceof Error &&
            (error.message.includes("Not Found") ||
              error.message.toLowerCase().includes("cannot be found"))
          ) {
            console.log(
              `Inbound trunk for agent phone number ${agentPhoneNumber.id} not found, continuing with creation`,
            );
          } else {
            throw error;
          }
        }
        const newInboundTrunk = await createInboundTrunk(agentPhoneNumber);
        agentPhoneNumber = await db.agentPhoneNumber.update({
          where: { id: agentPhoneNumber.id },
          data: { sipInboundTrunkId: newInboundTrunk.sipTrunkId },
        });

        // Update the agent phone number to use the new inbound trunk and dispatch rule.
        try {
          await deleteInboundDispatchRule(agentPhoneNumber.id);
        } catch (error) {
          if (
            error instanceof Error &&
            (error.message.includes("Not Found") ||
              error.message.toLowerCase().includes("cannot be found"))
          ) {
            console.log(
              `Inbound dispatch rule for agent phone number ${agentPhoneNumber.id} not found, continuing with creation`,
            );
          } else {
            throw error;
          }
        }
        const newInboundDispatchRule =
          await createInboundDispatchRule(agentPhoneNumber);
        await db.agentPhoneNumber.update({
          where: { id: agentPhoneNumber.id },
          data: {
            sipInboundDispatchRuleId: newInboundDispatchRule.sipDispatchRuleId,
          },
        });
        console.log(
          `Agent phone number ${agentPhoneNumber.id} has been updated with new inbound trunk and dispatch rule`,
        );
      }
    });
  },
);

