     1→import {
     2→  getEngagementForRoom,
     3→  markEngagementComplete,
     4→} from "@/server/libs/engagements";
     5→
     6→import { inngest } from "../client";
     7→import { MAX_INNGEST_PRIORITY, handleException } from "../utils";
     8→
     9→export const livekitRoomFinished = inngest.createFunction(
    10→  {
    11→    id: "livekit-room-finished",
    12→    priority: {
    13→      run: MAX_INNGEST_PRIORITY,
    14→    },
    15→  },
    16→  { event: "livekit/room.finished" },
    17→  async ({ event, step }) => {
    18→    const { roomName } = event.data;
    19→
    20→    // Wait 15 seconds before processing so avoid race conditions caused by Livekit
    21→    await step.sleep("livekit-room-finished-buffer", "15s");
    22→
    23→    const engagement = await step.run("get-engagement", async () => {
    24→      return await getEngagementForRoom(roomName);
    25→    });
    26→
    27→    if (engagement === null) {
    28→      console.log(
    29→        `No engagement found for room ${roomName}, skipping scorecard generation`,
    30→      );
    31→      return null;
    32→    }
    33→
    34→    await step.run("mark-engagement-complete", async () => {
    35→      try {
    36→        await markEngagementComplete(engagement.id);
    37→      } catch (error) {
