import {
  getEngagementForRoom,
  markEngagementComplete,
} from "@/server/libs/engagements";

import { inngest } from "../client";
import { MAX_INNGEST_PRIORITY, handleException } from "../utils";

export const livekitRoomFinished = inngest.createFunction(
  {
    id: "livekit-room-finished",
    priority: {
      run: MAX_INNGEST_PRIORITY,
    },
  },
  { event: "livekit/room.finished" },
  async ({ event, step }) => {
    const { roomName } = event.data;

    // Wait 15 seconds before processing so avoid race conditions caused by Livekit
    await step.sleep("livekit-room-finished-buffer", "15s");

    const engagement = await step.run("get-engagement", async () => {
      return await getEngagementForRoom(roomName);
    });

    if (engagement === null) {
      console.log(
        `No engagement found for room ${roomName}, skipping scorecard generation`,
      );
      return null;
    }

    await step.run("mark-engagement-complete", async () => {
      try {
        await markEngagementComplete(engagement.id);
      } catch (error) {
        handleException(error);
        console.error("Error marking engagement as complete:", error);
      }
    });

    await inngest.send({
      name: "purplefish/engagement.completed",
      data: {
        engagementId: engagement.id,
      },
    });

    return true;
  },
);

