   182→              id: true,
   183→              isBot: true,
   184→            },
   185→          },
   186→        },
   187→      },
   188→    },
   189→  });
   190→
   191→  if (!engagement.opportunity || !engagement.opportunityId) {
   192→    console.info(
   193→      `Opportunity not found for engagement ${engagementId} while generating score card`,
   194→    );
   195→    return null;
   196→  }
   197→
   198→  // For bots and when resume calls are disabled, only grade on this engagement.
   199→  // Otherwise, grade on the previous 3 including this one.
   200→  const take =
   201→    engagement.opportunity.candidate.isBot &&
   202→    !engagement.opportunity.job.resumeCallsEnabled
   203→      ? 1
   204→      : 3;
