   214→
   215→// To make life easier for the LLM, we map the message IDs to a sequential number.
   216→const messageIdMap = (engagements: { messages: Message[] }[]) => {
   217→  const map: Record<string, string> = {};
   218→  const reverseMap: Record<string, string> = {};
   219→  let i = 0;
   220→  for (const engagement of engagements) {
   221→    for (const message of engagement.messages) {
   222→      map[message.id] = i.toString();
   223→      reverseMap[i.toString()] = message.id;
   224→      i++;
   225→    }
   226→  }
   227→  return { map, reverseMap };
   228→};
