   232→  map: Record<string, string>,
   233→) =>
   234→  `<call>\n${messages.map((message) => `${message.role === "user" ? "Candidate" : message.role === "assistant" ? "Recruiter" : "System"} (${map[message.id]}): ${message.content}`).join("\n")}\n</call>`;
   235→
   236→const generateTranscriptForEngagements = (
   237→  engagements: { messages: Message[] }[],
   238→  map: Record<string, string>,
   239→) => {
   240→  const calls: string[] = [];
   241→  for (const engagement of engagements.reverse()) {
   242→    calls.push(generateTranscriptForEngagement(engagement.messages, map));
   243→  }
   244→  return `<calls>\n${calls.join("\n")}\n</calls>`;
   245→};
