   247→const generateRequirementsList = (requirements: Requirement[]) =>
   248→  `Based on the call(s) above, evaluate and fill out the following JSON:
   249→
   250→{
   251→  "scores": ${JSON.stringify(
   252→    requirements.map((requirement) => ({
   253→      requirement: {
   254→        value: requirement.requirement,
   255→        type: requirement.type,
   256→      },
   257→    })),
   258→    null,
   259→    2,
   260→  )},
   261→  "agreedSalary": <agreed salary or hourly wage from transcript or null if not found. For example, $45.50/hour should be 45.50, $50,000/year should be 50000. Be careful not to interpret other numbers (e.g. phone numbers and zip codes) as salary.>
   262→}`;
   263→
   264→const SCORE_CARD_PROMPT = `You are an expert reviewer of call transcripts.  Determine whether the job's requirements are met based on the transcript.
   265→
   266→Instructions:
   267→- Read the transcript carefully: Analyze the conversation between the candidate and the recruiter.
   268→- The transcript is from the oldest to the newest engagement.
   269→- Consider the whole conversation: Consider what the candidate's answer is in context of the whole conversation, not just individual messages.
   270→- Provide your reasoning and your answer.
   271→- The transcript is from a speech-to-text transcription service, so it may contain minor typos. Consider carefully the candidate's intent, and that this is spoken language, so numbers may come in in different formats (e.g. $45.50 might come in as 4550). Consider what would be reasonable in the context of the conversation.
   272→
   273→Generate a score card for the transcript. Use the following scale for scoring:
   274→* No data: The transcript does not provide any evidence for whether the candidate meets the requirement.
   275→* Did not meet: The candidate did not meet the requirement.
   276→* Met: The candidate met or exceeded the requirement.
   277→
   278→Use the type of the requirement to determine the score type.
   279→
   280→Additionally extract the agreed upon salary or hourly wage from the transcript, or null if not found.
   281→
   282→Keep in mind that these are job requirements, so for example if the candidate has more years of experience than required, or they want a lower salary than the maximum, that should be considered "Met".
   283→
   284→Generate output in the following JSON format:
   285→{
   286→  "scores": [
   287→    {
   288→      "requirement": "Requirement text",
   289→      "score": "No data" | "Did not meet" | "Met",
   290→      "type": "mandatory" | "preferred",
   291→      "evidence": "Evidence for the score",
   292→      "details": "Details about the score",
   293→      "messageId": "Message ID of the evidence",
   294→    }
   295→  ],
   296→  "agreedSalary": <agreed salary or hourly wage from transcript or null if not found. For example, $45.50/hour should be 45.50, $50,000/year should be 50000. Be careful not to interpret other numbers (e.g. phone numbers and zip codes) as salary.>
   297→}
   298→`;
