   300→const completeEngagement = async (
   301→  engagementId: string,
   302→  scoreCard: IScoreCard,
   303→  salaryRequirementCents: number | null,
   304→) => {
   305→  return await db.engagement.update({
   306→    where: { id: engagementId },
   307→    data: {
   308→      completedAt: new Date(),
   309→      scoreCard,
   310→      salaryRequirementCents,
   311→    },
   312→  });
   313→};
   314→
   315→const createNoDataScores = (requirements: Requirement[]) => {
   316→  return {
   317→    scores: requirements.map((r) => ({
   318→      requirement: r.requirement,
   319→      type: r.type,
   320→      messageId: null,
   321→      score: "No data" as const,
   322→      evidence: null,
   323→      details: null,
   324→    })),
   325→    agreedSalary: null,
   326→  };
   327→};
   328→
   329→const handleAgreedSalaryForOpportunity = async (
   330→  agreedSalary: number | null,
   331→  opportunity: OpportunityWithEngagementsToGrade,
   332→  engagementId: string,
   333→): Promise<number | null> => {
   334→  if (agreedSalary === null) {
   335→    console.info(
   336→      `No agreed salary found for engagement ${engagementId}, ` +
   337→        `not setting salary requirements for opportunity ${opportunity.id}`,
   338→    );
   339→    return null;
   340→  }
   341→
   342→  // Attempt to read the 'max_pay' job variable
   343→  const maxPayValue = opportunity.job.variables.find(
   344→    (v) => v.templateVariable.key === "max_pay",
   345→  )?.value;
   346→
   347→  if (!maxPayValue) {
   348→    console.error(
   349→      `Max pay value not found for job ${opportunity.job.id}, ` +
   350→        `not setting salary requirements for opportunity ${opportunity.id}`,
   351→      opportunity.job.variables,
   352→    );
   353→    return null;
   354→  }
   355→
   356→  const maxPay = Number(maxPayValue.replace(/[^0-9.]/g, ""));
   357→  if (agreedSalary > maxPay) {
   358→    agreedSalary = maxPay;
   359→  }
   360→
   361→  if (isNaN(agreedSalary) || !isFinite(agreedSalary)) {
   362→    console.error(
   363→      `Agreed salary is not a valid number: ${agreedSalary} ` +
   364→        `for opportunity ${opportunity.id}`,
   365→    );
   366→    return null;
   367→  }
   368→
   369→  // If valid, update the Opportunity record
   370→  const salaryRequirementCents = Math.round(agreedSalary * 100);
   371→  await db.opportunity.update({
   372→    where: { id: opportunity.id },
   373→    data: {
   374→      salaryRequirementCents,
   375→    },
   376→  });
   377→  return salaryRequirementCents;
   378→};
   379→
   380→const generateScoreCardWithMessageIds = async (
   381→  engagements: { messages: Message[] }[],
   382→  requirements: Requirement[],
   383→) => {
   384→  const { map, reverseMap } = messageIdMap(engagements);
   385→  const instructions = `${generateTranscriptForEngagements(engagements, map)}\n\n${generateRequirementsList(requirements)}`;
   386→
   387→  const result = await generateObject({
   388→    model: aiModel,
   389→    schema: scoreCardSchema,
   390→    messages: [
   391→      {
   392→        role: "system",
   393→        content: SCORE_CARD_PROMPT,
   394→      },
   395→      {
   396→        role: "user",
   397→        content: instructions,
   398→      },
   399→    ],
   400→  });
   401→  // Update the scorecard with the message IDs
   402→  return {
   403→    scores: result.object.scores.map((score) => ({
   404→      ...score,
   405→      messageId: score.messageId ? (reverseMap[score.messageId] ?? "") : "",
   406→    })),
   407→    agreedSalary: result.object.agreedSalary,
   408→  };
   409→};
   410→
   411→const generateScoreCardForOpportunity = async (
   412→  opportunity: OpportunityWithEngagementsToGrade,
   413→  engagementId: string,
   414→) => {
   415→  if (opportunity.job.callScript === null) {
   416→    return await completeEngagement(
   417→      engagementId,
   418→      {
   419→        scores: [],
   420→        agreedSalary: null,
   421→      },
   422→      null,
   423→    );
   424→  }
   425→
   426→  // If the engagement state is either voicemail or no answer, copy the scorecard from the previous engagement
   427→  // if it exists - otherwise, give it a blank scorecard.
   428→  const engagement = opportunity.engagements[0]!;
   429→  if (
   430→    engagement.subStatus === CallSubStatus.voicemail ||
   431→    engagement.subStatus === CallSubStatus.no_answer
   432→  ) {
   433→    if (opportunity.engagements.length > 1) {
   434→      const previousEngagement = opportunity.engagements[1]!;
   435→      if (previousEngagement.scoreCard !== null) {
   436→        return await completeEngagement(
   437→          engagementId,
   438→          previousEngagement.scoreCard as IScoreCard,
   439→          null,
   440→        );
   441→      }
   442→    }
   443→    return await completeEngagement(
   444→      engagementId,
   445→      {
   446→        scores: [],
   447→        agreedSalary: null,
   448→      },
   449→      null,
   450→    );
   451→  }
   452→  // If there's a successful engagement, copy the scorecard from THAT to the new engagement
   453→  if (
   454→    opportunity.engagements.some((e) => e.subStatus === CallSubStatus.completed)
   455→  ) {
   456→    const successfulEngagement = opportunity.engagements.find(
   457→      (e) => e.subStatus === CallSubStatus.completed,
   458→    )!;
   459→    return await completeEngagement(
   460→      engagementId,
   461→      successfulEngagement.scoreCard as IScoreCard,
   462→      null,
   463→    );
   464→  }
   465→
   466→  const callScript = parseScriptNodes(
   467→    opportunity.job.callScript as Prisma.JsonObject,
   468→  );
   469→
   470→  const requirements = getRequirementsFromScript(callScript);
   471→
   472→  const numMessages = opportunity.engagements.reduce(
   473→    (acc, engagement) => acc + engagement.messages.length,
   474→    0,
   475→  );
   476→
   477→  if (numMessages === 0) {
   478→    return await completeEngagement(
   479→      engagementId,
   480→      createNoDataScores(requirements),
   481→      null,
   482→    );
   483→  }
   484→
   485→  const result = await generateScoreCardWithMessageIds(
   486→    opportunity.engagements,
   487→    requirements,
   488→  );
   489→
   490→  const finalAgreedSalaryCents = await handleAgreedSalaryForOpportunity(
   491→    result.agreedSalary,
   492→    opportunity,
   493→    engagementId,
   494→  );
   495→
   496→  return await completeEngagement(
   497→    engagementId,
   498→    {
   499→      scores: result.scores,
   500→      agreedSalary: result.agreedSalary,
   501→    },
   502→    finalAgreedSalaryCents,
   503→  );
   504→};
