   521→export async function sendRecruiterEmail(engagementId: string) {
   522→  const engagement = await db.engagement.findUniqueOrThrow({
   523→    where: { id: engagementId },
   524→    include: {
   525→      opportunity: {
   526→        include: {
   527→          candidate: true,
   528→          job: {
   529→            include: {
   530→              variables: {
   531→                include: {
   532→                  templateVariable: true,
   533→                },
   534→              },
   535→              organization: {
   536→                select: {
   537→                  defaultRecruiter: true,
   538→                },
   539→              },
   540→            },
   541→          },
   542→        },
   543→      },
   544→    },
   545→  });
   546→
   547→  if (
   548→    engagement.recruiterEmailSentAt ||
   549→    engagement.status !== CallStatus.completed
   550→  ) {
   551→    return;
   552→  }
   553→
   554→  if (!engagement.opportunity) {
   555→    throw new Error(
   556→      `Engagement ${engagementId} has no opportunity in sendRecruiterEmail`,
   557→    );
   558→  }
   559→
   560→  const assignedToEmail = engagement.opportunity.assignedToEmail;
   561→
   562→  const defaultRecruiterEmail =
   563→    engagement.opportunity.job.organization.defaultRecruiter?.email;
   564→
   565→  const recruiterEmail =
   566→    assignedToEmail && assignedToEmail.length > 0
   567→      ? assignedToEmail
   568→      : defaultRecruiterEmail;
   569→
   570→  if (!recruiterEmail) {
