   576→
   577→  const firstName = engagement.opportunity.candidate.firstName;
   578→  const lastName = engagement.opportunity.candidate.lastName;
   579→
   580→  const job = {
   581→    ...engagement.opportunity.job,
   582→    companyName: getJobVariableValue(
   583→      engagement.opportunity.job.variables,
   584→      variableKeys.CLIENT_NAME,
   585→    ),
   586→  };
   587→
   588→  const url = `/organizations/${engagement.opportunity.job.organizationId}/jobs/${engagement.opportunity.job.id}/opportunities/${engagement.opportunity.id}/overview`;
   589→
   590→  await sendRecruiterEmailAction({
