   607→/**
   608→ * Returns whether the required nodes in the call script were reached during this engagement.
   609→ */
   610→function hasReachedAllRequiredNodes(
   611→  agentTaskEvents: EngagementAgentTaskEvent[],
   612→  allScriptNodes: ScriptNode[],
   613→): boolean {
   614→  // Get all required nodes at the top level
   615→  const requiredNodes = allScriptNodes.filter(
   616→    (node) =>
   617→      node.required &&
   618→      node.requirementType === JobQualificationType.MANDATORY &&
   619→      !node.conditionToEnter,
   620→  );
   621→
   622→  // If no required nodes, check if they reached the last node in the script
   623→  if (requiredNodes.length === 0) {
   624→    const lastNodeId = allScriptNodes[allScriptNodes.length - 1]?.id;
   625→    return agentTaskEvents.some(
   626→      (event) =>
   627→        event.type === EngagementAgentTaskEventType.task_popped &&
   628→        event.taskId === lastNodeId,
   629→    );
   630→  }
   631→
   632→  // Get all completed task IDs
   633→  const completedTaskIds = agentTaskEvents
   634→    .filter((event) => event.type === EngagementAgentTaskEventType.task_popped)
   635→    .map((event) => event.taskId);
   636→  // Check if all required nodes have been completed
   637→  return requiredNodes.every((node) => completedTaskIds.includes(node.id));
   638→}
