   656→export async function generateTranscriptSummary(engagementId: string) {
   657→  const engagement = await db.engagement.findUniqueOrThrow({
   658→    where: { id: engagementId },
   659→    select: {
   660→      subStatus: true,
   661→      messages: true,
   662→      opportunity: {
   663→        select: {
   664→          job: {
   665→            select: {
   666→              organizationId: true,
   667→              transcriptSummaryInstructions: true,
   668→            },
   669→          },
   670→        },
   671→      },
   672→    },
   673→  });
   674→
   675→  if (!engagement.opportunity) {
   676→    throw new Error(
   677→      `Opportunity not found for engagement id: ${engagementId} while generating transcript summary`,
   678→    );
   679→  }
   680→
   681→  const organizationId = engagement.opportunity.job.organizationId;
   682→
   683→  if (
   684→    engagement.subStatus !== CallSubStatus.completed &&
   685→    engagement.subStatus !== CallSubStatus.partial
   686→  ) {
   687→    return null;
   688→  }
   689→
   690→  // Check for job-level instructions first, then fall back to organization-level
   691→  const jobInstructions =
   692→    engagement.opportunity.job.transcriptSummaryInstructions;
   693→
   694→  let transcriptSummaryInstructions: string | null = jobInstructions;
   695→
   696→  if (!transcriptSummaryInstructions) {
   697→    const organization = await db.organization.findUniqueOrThrow({
   698→      where: {
   699→        id: organizationId,
   700→      },
   701→      select: {
   702→        transcriptSummaryInstructions: true,
   703→      },
   704→    });
   705→
   706→    transcriptSummaryInstructions = organization.transcriptSummaryInstructions;
   707→  }
   708→
   709→  if (!transcriptSummaryInstructions) {
   710→    return null;
   711→  }
   712→
   713→  const { map } = messageIdMap([engagement]);
   714→  const transcript = generateTranscriptForEngagement(
   715→    // We don't include system messages because they are not part of the conversation
   716→    // LLM takes "candidate hung up" system message as a sign that the candidate declined the job (which is incorrect)
   717→    engagement.messages.filter((message) => message.role !== "system"),
   718→    map,
   719→  );
   720→
   721→  const prompt = `${transcriptSummaryInstructions}
   722→
   723→<transcript>
   724→${transcript}
   725→</transcript>
   726→`;
   727→
   728→  const existingSummary = await db.engagementTranscriptSummary.findUnique({
   729→    where: { engagementId },
   730→  });
   731→
   732→  if (existingSummary?.prompt === prompt) {
   733→    return existingSummary;
   734→  }
   735→
   736→  const result = await generateText({
   737→    model: aiModel,
   738→    prompt,
   739→  });
   740→
   741→  if (!result.text) {
   742→    return null;
   743→  }
   744→
   745→  return await db.engagementTranscriptSummary.upsert({
   746→    where: { engagementId },
   747→    update: { summary: result.text, prompt },
   748→    create: { engagementId, summary: result.text, prompt },
   749→  });
   750→}
