   752→export async function computeCallStatus(engagementId: string): Promise<{
   753→  id: string;
   754→  status: CallStatus;
   755→  subStatus: CallSubStatus;
   756→  durationSeconds: number;
   757→  candidateDeclineReason: string | null;
   758→} | null> {
   759→  const engagement = await db.engagement.findUniqueOrThrow({
   760→    where: { id: engagementId },
   761→    select: {
   762→      id: true,
   763→      roomName: true,
   764→      createdAt: true,
   765→      completedAt: true,
   766→      candidateDeclineReason: true,
   767→      scriptNodes: true,
   768→      rescheduledAt: true,
   769→      subStatus: true,
   770→      opportunity: {
   771→        select: {
   772→          id: true,
   773→          agentVersion: true,
   774→          job: {
   775→            select: { callScript: true, resumeCallsEnabled: true },
   776→          },
   777→          candidate: {
   778→            select: { isBot: true },
   779→          },
   780→        },
   781→      },
   782→      messages: {
   783→        orderBy: { createdAt: "asc" },
   784→        select: {
   785→          id: true,
   786→          role: true,
   787→          stateType: true,
   788→          createdAt: true,
   789→          content: true,
   790→        },
   791→      },
   792→    },
   793→  });
   794→
   795→  if (!engagement.opportunity) {
   796→    console.log(
   797→      `No opportunity found for engagement ${engagementId} when computing call status`,
   798→    );
   799→    return null;
   800→  }
   801→
   802→  const callScript = engagement.opportunity.job.callScript;
   803→
   804→  // Find all task events up to this point in time
   805→  const takeMultiple =
   806→    !engagement.opportunity.candidate.isBot &&
   807→    engagement.opportunity.job.resumeCallsEnabled;
   808→
   809→  const agentTaskEvents = takeMultiple
   810→    ? await db.engagementAgentTaskEvent.findMany({
   811→        where: {
   812→          engagement: {
   813→            OR: [
   814→              {
   815→                opportunityId: engagement.opportunity.id,
   816→                createdAt: {
   817→                  lte: engagement.createdAt,
   818→                },
   819→              },
   820→              {
   821→                id: engagement.id,
   822→              },
   823→            ],
   824→          },
   825→        },
   826→        orderBy: { occurredAt: "asc" },
   827→      })
   828→    : await db.engagementAgentTaskEvent.findMany({
   829→        where: {
   830→          engagementId: engagement.id,
   831→        },
   832→        orderBy: { occurredAt: "asc" },
   833→      });
   834→
   835→  // If there are agent task events, ignore the script nodes (legacy logic)
   836→  const allScriptNodes = parseScriptNodes(
   837→    callScript as Prisma.JsonObject,
   838→  ).nodes;
   839→
   840→  const nonSystemMessages = engagement.messages.filter(
   841→    (message) => message.role !== "system",
   842→  );
   843→
   844→  const userMessages = nonSystemMessages.filter(
   845→    (message) => message.role === "user",
   846→  );
   847→
   848→  // Get the time user stays on the call
   849→  // the duration between when the call started and when the user last spoke
   850→  const lastUserMessage = userMessages[userMessages.length - 1];
   851→  const interactiveDurationMs = lastUserMessage
   852→    ? lastUserMessage.createdAt.getTime() - engagement.createdAt.getTime()
   853→    : 0;
   854→
   855→  const quickHangupThresholdMs = 1000 * 60; // 60 seconds
   856→
   857→  const whoHangup: "agent" | "candidate" = engagement.messages.some(
   858→    (message) =>
   859→      message.role === "system" &&
   860→      message.content
   861→        .toUpperCase()
   862→        .includes("CANDIDATE HAS BEEN SILENT FOR TOO LONG"),
   863→  )
   864→    ? "agent"
   865→    : "candidate";
   866→
   867→  let subStatus: CallSubStatus = (() => {
   868→    if (engagement.candidateDeclineReason) {
   869→      return CallSubStatus.candidate_declined;
   870→    }
   871→
   872→    // If the call doesn't have a completion time, it's still in progress
   873→    if (!engagement.completedAt) {
   874→      return CallSubStatus.in_progress;
   875→    }
   876→
   877→    if (engagement.rescheduledAt) {
   878→      return CallSubStatus.rescheduled;
   879→    }
   880→
   881→    // If last node in the script was reached, it's a success
   882→    const isCompleted = hasReachedAllRequiredNodes(
   883→      agentTaskEvents,
   884→      allScriptNodes,
   885→    );
   886→    if (isCompleted) {
   887→      return CallSubStatus.completed;
   888→    }
   889→
   890→    // If there are no messages, assume the call was not answered
   891→    if (userMessages.length < 1) {
   892→      return CallSubStatus.no_answer;
   893→    }
   894→    const isOutbound = engagement.roomName?.startsWith("profileId:");
   895→
   896→    // If voicemail script node or voicemail message is present, it's a voicemail
   897→    if (isOutbound) {
   898→      const foundVoicemailTask = agentTaskEvents.find(
   899→        (event) =>
   900→          event.engagementId === engagement.id && event.taskId === "voicemail",
   901→      );
   902→      const foundVoicemailMessage = engagement.messages.find(
   903→        (message) =>
   904→          message.role === "system" &&
   905→          message.content.toUpperCase().includes("VOICEMAIL"),
   906→      );
   907→
   908→      if (foundVoicemailTask || foundVoicemailMessage) {
   909→        return CallSubStatus.voicemail;
   910→      }
   911→    }
   912→
   913→    // If the call ends very early (after 1 message or 60 seconds), it could be a quick hangup or a voicemail
   914→    if (
   915→      userMessages.length === 1 ||
   916→      interactiveDurationMs < quickHangupThresholdMs
   917→    ) {
   918→      // If the phone ends early, and the agent hangup the call (not the candidate), assume it's a voicemail
   919→      if (isOutbound && whoHangup === "agent") {
   920→        return CallSubStatus.voicemail;
   921→      }
   922→
   923→      return CallSubStatus.quick_hangup;
   924→    }
   925→
   926→    return CallSubStatus.partial;
   927→  })();
   928→
   929→  const lastMessage = engagement.messages[engagement.messages.length - 1];
   930→  let durationSeconds =
   931→    lastMessage && subStatus !== CallSubStatus.in_progress
   932→      ? (lastMessage.createdAt.getTime() - engagement.createdAt.getTime()) /
   933→        1000
   934→      : undefined;
   935→  if (subStatus === CallSubStatus.no_answer) {
   936→    durationSeconds = 0;
   937→  }
   938→
   939→  if (
   940→    subStatus === CallSubStatus.partial ||
   941→    subStatus === CallSubStatus.quick_hangup
   942→  ) {
   943→    const candidateDecline = await computeCandidateDecline(engagementId);
   944→    if (candidateDecline.candidateDeclined) {
   945→      subStatus = CallSubStatus.candidate_declined;
   946→    } else {
   947→      const rejection = await computeRejection(engagementId);
   948→      if (rejection.rejected) {
   949→        subStatus = CallSubStatus.rejected;
   950→      }
   951→    }
   952→  }
   953→
   954→  const updatedEngagement = await db.engagement.update({
   955→    where: { id: engagementId },
   956→    data: {
   957→      status: getCallStatusFromSubstatus(subStatus),
   958→      subStatus,
   959→      durationSeconds,
   960→      statusComputedAt: new Date(),
   961→    },
   962→    select: {
   963→      id: true,
   964→      status: true,
   965→      subStatus: true,
   966→      durationSeconds: true,
   967→      candidateDeclineReason: true,
   968→      rejectionReason: true,
   969→    },
   970→  });
   971→
   972→  await computeOpportunityStatus(engagement.opportunity.id);
   973→
   974→  await generateTranscriptSummary(engagementId);
   975→
   976→  return updatedEngagement;
   977→}
