  1040→export const upsertEngagementScriptNodes = async (
  1041→  engagementId: string,
  1042→  newScriptNode: z.infer<typeof EngagementScriptNodeSchema>,
  1043→) => {
  1044→  const engagement = await db.engagement.findUniqueOrThrow({
  1045→    where: { id: engagementId },
