  1048→  const oldScriptNodes = Array.isArray(engagement.scriptNodes)
  1049→    ? (engagement.scriptNodes as z.infer<typeof EngagementScriptNodeSchema>[])
  1050→    : [];
  1051→
  1052→  // Update the script node if it already exists, otherwise add it
  1053→  const newScriptNodes = oldScriptNodes.map((scriptNode) => {
  1054→    if (scriptNode.id === newScriptNode.id) {
  1055→      return newScriptNode;
  1056→    }
  1057→    return scriptNode;
  1058→  });
  1059→
  1060→  const found = newScriptNodes.find(
  1061→    (scriptNode) => scriptNode.id === newScriptNode.id,
  1062→  );
  1063→  if (!found) {
  1064→    newScriptNodes.push(newScriptNode);
  1065→  }
  1066→
  1067→  return await db.engagement.update({
  1068→    where: { id: engagementId },
  1069→    data: {
  1070→      scriptNodes: newScriptNodes,
  1071→    },
  1072→  });
  1073→};
