  1075→export const detectDoNotCallRequested = async (
  1076→  engagementId: string,
  1077→): Promise<z.infer<typeof doNotCallSchema>> => {
  1078→  const engagementWithMessages = await db.engagement.findUniqueOrThrow({
  1079→    where: { id: engagementId },
  1080→    include: {
  1081→      messages: {
  1082→        orderBy: {
  1083→          createdAt: "asc",
  1084→        },
  1085→      },
  1086→    },
  1087→  });
  1088→
  1089→  if (
  1090→    engagementWithMessages.messages.filter((message) => message.role === "user")
  1091→      .length === 0
  1092→  ) {
  1093→    return {
  1094→      doNotCall: false,
  1095→      reasoning: "No user messages found",
  1096→    };
  1097→  }
  1098→
  1099→  // ensure this engagement had a conversation with the candidate that could have contained a do-not-call request:
  1100→  // The engagement state is not one of: voicemail, no-answer, success
  1101→  if (
  1102→    engagementWithMessages.subStatus === CallSubStatus.voicemail ||
  1103→    engagementWithMessages.subStatus === CallSubStatus.no_answer ||
  1104→    engagementWithMessages.subStatus === CallSubStatus.completed
  1105→  ) {
  1106→    return {
  1107→      doNotCall: false,
  1108→      reasoning: "Engagement state is not voicemail, no-answer, or success",
  1109→    };
  1110→  }
  1111→  // ensure the length of the audio is greater than 0
  1112→  if (engagementWithMessages.durationSeconds === 0) {
  1113→    return {
  1114→      doNotCall: false,
  1115→      reasoning: "Engagement duration is 0",
  1116→    };
  1117→  }
  1118→
  1119→  const { map } = messageIdMap([engagementWithMessages]);
  1120→  const transcript = generateTranscriptForEngagement(
  1121→    engagementWithMessages.messages,
  1122→    map,
  1123→  );
  1124→
  1125→  const result = await generateObject({
  1126→    model: aiModel,
  1127→    schema: doNotCallSchema,
  1128→    prompt: `**Instruction:**
  1129→Your goal is to determine whether, in the conversation below, the candidate explicitly requests **not** to be contacted again or to be removed from any call or contact lists. 
  1130→
  1131→**Definition of an explicit do-not-call request:**
  1132→- Statements from the candidate such as "take me off your list," "don't call me again," "remove my number," "do not contact me,"  or any clear variant that directly indicates they wish to end all future contact.
  1133→- Clearly conveys that they want no further contact, even if it's not in those exact words. This may include:
  1134→  - Extreme rudeness or profanity directed at ending the call or dismissing the recruiter (e.g., "fuck off," "stop calling," "leave me alone," etc.).
  1135→  - Other language that unequivocally shows the candidate does not want to be contacted again.
  1136→
  1137→**What does *not* count as an explicit do-not-call request?**
  1138→- An empty transcript is not an explicit do-not-call request.
  1139→- Voicemail is not an explicit do-not-call request.
  1140→- Saying "this isn't a good time," or "I have to go" is *not* an explicit do-not-call request.
  1141→- Declining the job or saying that they are not interested in the role is *not* an explicit do-not-call request.
  1142→- An empty transcript or a hangup that doesn't come with other evidence is *not* an explicit do-not-call request.
  1143→
  1144→**Task:**
  1145→Read the transcript below and decide:
  1146→1. Reasoning for the decision of whether this is a do-not-call request, including a relevant quote from the transcript.
  1147→2. Whether the candidate explicitly requested to end all future contact (using phrases similar to the examples above)
  1148→
  1149→Use the attached JSON schema to format your response.
  1150→
  1151→**Transcript:**
  1152→${transcript}`,
  1153→  });
  1154→
  1155→  return result.object;
  1156→};
  1157→
  1158→const computeCandidateDecline = async (
  1159→  engagementId: string,
  1160→): Promise<{
  1161→  candidateDeclined: boolean;
  1162→  candidateDeclineReason: string | null;
  1163→}> => {
  1164→  const engagementWithMessages = await db.engagement.findUniqueOrThrow({
  1165→    where: { id: engagementId },
  1166→    include: {
  1167→      messages: {
  1168→        orderBy: {
  1169→          createdAt: "asc",
  1170→        },
  1171→      },
  1172→    },
  1173→  });
  1174→
  1175→  if (engagementWithMessages.candidateDeclineCheckedAt) {
  1176→    return {
  1177→      candidateDeclined: Boolean(engagementWithMessages.candidateDeclineReason),
  1178→      candidateDeclineReason: engagementWithMessages.candidateDeclineReason,
  1179→    };
  1180→  }
  1181→
  1182→  const { map } = messageIdMap([engagementWithMessages]);
  1183→  const transcript = generateTranscriptForEngagement(
  1184→    // We don't include system messages because they are not part of the conversation
  1185→    // LLM takes "candidate hung up" system message as a sign that the candidate declined the job (which is incorrect)
  1186→    engagementWithMessages.messages.filter(
  1187→      (message) => message.role !== "system",
  1188→    ),
  1189→    map,
  1190→  );
  1191→
  1192→  const result = await generateObject({
  1193→    model: aiModel,
  1194→    schema: z.object({
  1195→      // Put candidateDeclineReason before candidateDeclined to force LLM to reason first
  1196→      candidateDeclineReason: z
  1197→        .string()
  1198→        .nullable()
  1199→        .describe("The reason for the candidate decline"),
  1200→      candidateDeclined: z.boolean().describe("Whether the candidate declined"),
  1201→    }),
  1202→    prompt: `**Instruction:**
  1203→Based on the transcript below, determine if the candidate declined the job. If so, provide a reason for the decline.
  1204→
  1205→Indicators that the candidate has declined the job:
  1206→- They explicitly express disinterest in the role (e.g., "I'm not interested").
  1207→- They say they are unavailable or not looking for a job.
  1208→- They request no further contact (e.g., "Take me off your list," "Don't call me again," "Remove my number," "Do not contact me").
  1209→
  1210→Important Notes:
  1211→- If the recruiter rejects the candidate, it should NOT be considered a candidate decline.
  1212→- Do not assume the candidate declined the job if you don't have enough information.
  1213→- If the candidate requests to reschedule or be contacted later, it should NOT be considered a decline.
  1214→
  1215→Use the attached JSON schema to format your response.
  1216→  
  1217→**Transcript:**
  1218→${transcript}`,
  1219→  });
  1220→
  1221→  const { candidateDeclined, candidateDeclineReason } = result.object;
  1222→
  1223→  // Computing the candidate decline reason is expensive, so we store the result in db to avoid recomputing it
  1224→  await db.engagement.update({
  1225→    where: { id: engagementId },
  1226→    data: {
  1227→      candidateDeclineCheckedAt: new Date(),
  1228→      candidateDeclineReason: candidateDeclined ? candidateDeclineReason : null,
  1229→    },
  1230→  });
  1231→
  1232→  // Populate the opportunity with the candidate decline reason
  1233→  if (candidateDeclined) {
  1234→    if (engagementWithMessages.opportunityId) {
  1235→      await db.opportunity.update({
  1236→        where: { id: engagementWithMessages.opportunityId },
  1237→        data: {
  1238→          candidateDeclineReason,
  1239→        },
  1240→      });
  1241→    }
  1242→  }
  1243→
  1244→  return {
  1245→    candidateDeclined,
  1246→    candidateDeclineReason,
  1247→  };
  1248→};
  1249→
  1250→const computeRejection = async (
  1251→  engagementId: string,
  1252→): Promise<{
  1253→  rejected: boolean;
  1254→  rejectionReason: string | null;
  1255→}> => {
