"use server";

import { generateObject, generateText } from "ai";
import { z } from "zod";

import {
  CallStatus,
  CallSubStatus,
  Engagement,
  EngagementAgentTaskEvent,
  EngagementAgentTaskEventType,
  EngagementIssue,
  type Message,
  OpportunityStatus,
  type Prisma,
} from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";

import { EngagementScriptNodeSchema } from "@/common/libs/engagement-script-node-schema";
import { getCallStatusFromSubstatus } from "@/common/libs/get-call-status-from-substatus";
import {
  type Requirement,
  getJobVariableValue,
  getRequirementsFromScript,
  variableKeys,
} from "@/common/libs/variables";
import { type IScoreCard, scoreCardSchema } from "@/common/models/engagements";
import { JobQualificationType } from "@/common/models/jobs";
import { ScriptNode, parseScriptNodes } from "@/common/models/script-nodes";
import { inngest } from "@/server/inngest/client";
import { sendRecruiterEmailAction } from "@/server/libs/emails";
import { deleteRoom } from "@/server/libs/livekit";
import { doNotCallSchema } from "@/server/libs/types";

import { aiModel } from "./ai-model";
import { computeOpportunityStatus } from "./opportunities";
import { formatScoreCard } from "./requirement-headings";

export type EngagementWithIssues = Engagement & {
  engagementIssues: EngagementIssue[];
};

export const upsertEngagement = async ({
  opportunityId,
  roomName,
  candidateId,
}: {
  opportunityId: string;
  roomName?: string;
  candidateId: string;
}): Promise<{
  id: string;
  createdAt: Date;
  updatedAt: Date;
  opportunityId: string;
  roomName: string | null;
  isNewlyCreated: boolean;
}> => {
  const existingEngagement = roomName
    ? await db.engagement.findFirst({
        where: {
          opportunityId,
          roomName,
        },
      })
    : null;

  if (existingEngagement) {
    return {
      ...existingEngagement,
      opportunityId: existingEngagement.opportunityId!,
      isNewlyCreated: false,
    };
  }

  const newEngagement = await db.engagement.create({
    data: {
      opportunityId,
      roomName,
      candidateId,
    },
    select: {
      id: true,
      createdAt: true,
      updatedAt: true,
      opportunityId: true,
      roomName: true,
    },
  });

  console.log(
    `New engagement created with opportunityId: ${opportunityId}, roomName: ${roomName}, candidateId: ${candidateId} and engagementId: ${newEngagement.id}`,
  );

  await db.opportunity.updateMany({
    where: { id: opportunityId, status: OpportunityStatus.not_contacted },
    data: {
      status: OpportunityStatus.in_progress,
    },
  });

  await inngest.send({
    name: "purplefish/engagement.created",
    data: {
      engagementId: newEngagement.id,
    },
  });

  return {
    ...newEngagement,
    opportunityId: newEngagement.opportunityId!,
    isNewlyCreated: true,
  };
};

const getOpportunityWithEngagementsToGrade = async (
  opportunityId: string,
  engagementCreatedAt: Date,
  take: number,
) => {
  return await db.opportunity.findUniqueOrThrow({
    where: {
      id: opportunityId,
    },
    include: {
      job: {
        include: {
          variables: {
            include: {
              templateVariable: true,
            },
          },
        },
      },
      engagements: {
        include: {
          messages: {
            orderBy: {
              createdAt: "asc",
            },
          },
        },
        where: {
          createdAt: {
            lte: engagementCreatedAt,
          },
        },
        orderBy: {
          // Note: It's important that we order by descending here so that we can
          // get the latest engagements.
          createdAt: "desc",
        },
        take,
      },
    },
  });
};
type OpportunityWithEngagementsToGrade = Prisma.PromiseReturnType<
  typeof getOpportunityWithEngagementsToGrade
>;

export const generateScoreCardForOpportunityEngagement = async (
  engagementId: string,
) => {
  const engagement = await db.engagement.findUniqueOrThrow({
    where: {
      id: engagementId,
    },
    select: {
      createdAt: true,
      opportunityId: true,
      opportunity: {
        select: {
          id: true,
          job: {
            select: {
              resumeCallsEnabled: true,
            },
          },
          candidate: {
            select: {
              id: true,
              isBot: true,
            },
          },
        },
      },
    },
  });

  if (!engagement.opportunity || !engagement.opportunityId) {
    console.info(
      `Opportunity not found for engagement ${engagementId} while generating score card`,
    );
    return null;
  }

  // For bots and when resume calls are disabled, only grade on this engagement.
  // Otherwise, grade on the previous 3 including this one.
  const take =
    engagement.opportunity.candidate.isBot &&
    !engagement.opportunity.job.resumeCallsEnabled
      ? 1
      : 3;

  const opportunity = await getOpportunityWithEngagementsToGrade(
    engagement.opportunityId,
    engagement.createdAt,
    take,
  );

  return await generateScoreCardForOpportunity(opportunity, engagementId);
};

// To make life easier for the LLM, we map the message IDs to a sequential number.
const messageIdMap = (engagements: { messages: Message[] }[]) => {
  const map: Record<string, string> = {};
  const reverseMap: Record<string, string> = {};
  let i = 0;
  for (const engagement of engagements) {
    for (const message of engagement.messages) {
      map[message.id] = i.toString();
      reverseMap[i.toString()] = message.id;
      i++;
    }
  }
  return { map, reverseMap };
};

const generateTranscriptForEngagement = (
  messages: Message[],
  map: Record<string, string>,
) =>
  `<call>\n${messages.map((message) => `${message.role === "user" ? "Candidate" : message.role === "assistant" ? "Recruiter" : "System"} (${map[message.id]}): ${message.content}`).join("\n")}\n</call>`;

const generateTranscriptForEngagements = (
  engagements: { messages: Message[] }[],
  map: Record<string, string>,
) => {
  const calls: string[] = [];
  for (const engagement of engagements.reverse()) {
    calls.push(generateTranscriptForEngagement(engagement.messages, map));
  }
  return `<calls>\n${calls.join("\n")}\n</calls>`;
};

const generateRequirementsList = (requirements: Requirement[]) =>
  `Based on the call(s) above, evaluate and fill out the following JSON:

{
  "scores": ${JSON.stringify(
    requirements.map((requirement) => ({
      requirement: {
        value: requirement.requirement,
        type: requirement.type,
      },
    })),
    null,
    2,
  )},
  "agreedSalary": <agreed salary or hourly wage from transcript or null if not found. For example, $45.50/hour should be 45.50, $50,000/year should be 50000. Be careful not to interpret other numbers (e.g. phone numbers and zip codes) as salary.>
}`;

const SCORE_CARD_PROMPT = `You are an expert reviewer of call transcripts.  Determine whether the job's requirements are met based on the transcript.

Instructions:
- Read the transcript carefully: Analyze the conversation between the candidate and the recruiter.
- The transcript is from the oldest to the newest engagement.
- Consider the whole conversation: Consider what the candidate's answer is in context of the whole conversation, not just individual messages.
- Provide your reasoning and your answer.
- The transcript is from a speech-to-text transcription service, so it may contain minor typos. Consider carefully the candidate's intent, and that this is spoken language, so numbers may come in in different formats (e.g. $45.50 might come in as 4550). Consider what would be reasonable in the context of the conversation.

Generate a score card for the transcript. Use the following scale for scoring:
* No data: The transcript does not provide any evidence for whether the candidate meets the requirement.
* Did not meet: The candidate did not meet the requirement.
* Met: The candidate met or exceeded the requirement.

Use the type of the requirement to determine the score type.

Additionally extract the agreed upon salary or hourly wage from the transcript, or null if not found.

Keep in mind that these are job requirements, so for example if the candidate has more years of experience than required, or they want a lower salary than the maximum, that should be considered "Met".

Generate output in the following JSON format:
{
  "scores": [
    {
      "requirement": "Requirement text",
      "score": "No data" | "Did not meet" | "Met",
      "type": "mandatory" | "preferred",
      "evidence": "Evidence for the score",
      "details": "Details about the score",
      "messageId": "Message ID of the evidence",
    }
  ],
  "agreedSalary": <agreed salary or hourly wage from transcript or null if not found. For example, $45.50/hour should be 45.50, $50,000/year should be 50000. Be careful not to interpret other numbers (e.g. phone numbers and zip codes) as salary.>
}
`;

const completeEngagement = async (
  engagementId: string,
  scoreCard: IScoreCard,
  salaryRequirementCents: number | null,
) => {
  return await db.engagement.update({
    where: { id: engagementId },
    data: {
      completedAt: new Date(),
      scoreCard,
      salaryRequirementCents,
    },
  });
};

const createNoDataScores = (requirements: Requirement[]) => {
  return {
    scores: requirements.map((r) => ({
      requirement: r.requirement,
      type: r.type,
      messageId: null,
      score: "No data" as const,
      evidence: null,
      details: null,
    })),
    agreedSalary: null,
  };
};

const handleAgreedSalaryForOpportunity = async (
  agreedSalary: number | null,
  opportunity: OpportunityWithEngagementsToGrade,
  engagementId: string,
): Promise<number | null> => {
  if (agreedSalary === null) {
    console.info(
      `No agreed salary found for engagement ${engagementId}, ` +
        `not setting salary requirements for opportunity ${opportunity.id}`,
    );
    return null;
  }

  // Attempt to read the 'max_pay' job variable
  const maxPayValue = opportunity.job.variables.find(
    (v) => v.templateVariable.key === "max_pay",
  )?.value;

  if (!maxPayValue) {
    console.error(
      `Max pay value not found for job ${opportunity.job.id}, ` +
        `not setting salary requirements for opportunity ${opportunity.id}`,
      opportunity.job.variables,
    );
    return null;
  }

  const maxPay = Number(maxPayValue.replace(/[^0-9.]/g, ""));
  if (agreedSalary > maxPay) {
    agreedSalary = maxPay;
  }

  if (isNaN(agreedSalary) || !isFinite(agreedSalary)) {
    console.error(
      `Agreed salary is not a valid number: ${agreedSalary} ` +
        `for opportunity ${opportunity.id}`,
    );
    return null;
  }

  // If valid, update the Opportunity record
  const salaryRequirementCents = Math.round(agreedSalary * 100);
  await db.opportunity.update({
    where: { id: opportunity.id },
    data: {
      salaryRequirementCents,
    },
  });
  return salaryRequirementCents;
};

const generateScoreCardWithMessageIds = async (
  engagements: { messages: Message[] }[],
  requirements: Requirement[],
) => {
  const { map, reverseMap } = messageIdMap(engagements);
  const instructions = `${generateTranscriptForEngagements(engagements, map)}\n\n${generateRequirementsList(requirements)}`;

  const result = await generateObject({
    model: aiModel,
    schema: scoreCardSchema,
    messages: [
      {
        role: "system",
        content: SCORE_CARD_PROMPT,
      },
      {
        role: "user",
        content: instructions,
      },
    ],
  });
  // Update the scorecard with the message IDs
  return {
    scores: result.object.scores.map((score) => ({
      ...score,
      messageId: score.messageId ? (reverseMap[score.messageId] ?? "") : "",
    })),
    agreedSalary: result.object.agreedSalary,
  };
};

const generateScoreCardForOpportunity = async (
  opportunity: OpportunityWithEngagementsToGrade,
  engagementId: string,
) => {
  if (opportunity.job.callScript === null) {
    return await completeEngagement(
      engagementId,
      {
        scores: [],
        agreedSalary: null,
      },
      null,
    );
  }

  // If the engagement state is either voicemail or no answer, copy the scorecard from the previous engagement
  // if it exists - otherwise, give it a blank scorecard.
  const engagement = opportunity.engagements[0]!;
  if (
    engagement.subStatus === CallSubStatus.voicemail ||
    engagement.subStatus === CallSubStatus.no_answer
  ) {
    if (opportunity.engagements.length > 1) {
      const previousEngagement = opportunity.engagements[1]!;
      if (previousEngagement.scoreCard !== null) {
        return await completeEngagement(
          engagementId,
          previousEngagement.scoreCard as IScoreCard,
          null,
        );
      }
    }
    return await completeEngagement(
      engagementId,
      {
        scores: [],
        agreedSalary: null,
      },
      null,
    );
  }
  // If there's a successful engagement, copy the scorecard from THAT to the new engagement
  if (
    opportunity.engagements.some((e) => e.subStatus === CallSubStatus.completed)
  ) {
    const successfulEngagement = opportunity.engagements.find(
      (e) => e.subStatus === CallSubStatus.completed,
    )!;
    return await completeEngagement(
      engagementId,
      successfulEngagement.scoreCard as IScoreCard,
      null,
    );
  }

  const callScript = parseScriptNodes(
    opportunity.job.callScript as Prisma.JsonObject,
  );

  const requirements = getRequirementsFromScript(callScript);

  const numMessages = opportunity.engagements.reduce(
    (acc, engagement) => acc + engagement.messages.length,
    0,
  );

  if (numMessages === 0) {
    return await completeEngagement(
      engagementId,
      createNoDataScores(requirements),
      null,
    );
  }

  const result = await generateScoreCardWithMessageIds(
    opportunity.engagements,
    requirements,
  );

  const finalAgreedSalaryCents = await handleAgreedSalaryForOpportunity(
    result.agreedSalary,
    opportunity,
    engagementId,
  );

  return await completeEngagement(
    engagementId,
    {
      scores: result.scores,
      agreedSalary: result.agreedSalary,
    },
    finalAgreedSalaryCents,
  );
};

export async function sendRoomFinishedEvent(engagementId: string) {
  const engagement = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
  });
  if (!engagement.roomName) {
    throw new Error("Room name not found for engagement");
  }
  await inngest.send({
    name: "livekit/room.finished",
    data: {
      roomName: engagement.roomName,
    },
  });
}

export async function sendRecruiterEmail(engagementId: string) {
  const engagement = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
    include: {
      opportunity: {
        include: {
          candidate: true,
          job: {
            include: {
              variables: {
                include: {
                  templateVariable: true,
                },
              },
              organization: {
                select: {
                  defaultRecruiter: true,
                },
              },
            },
          },
        },
      },
    },
  });

  if (
    engagement.recruiterEmailSentAt ||
    engagement.status !== CallStatus.completed
  ) {
    return;
  }

  if (!engagement.opportunity) {
    throw new Error(
      `Engagement ${engagementId} has no opportunity in sendRecruiterEmail`,
    );
  }

  const assignedToEmail = engagement.opportunity.assignedToEmail;

  const defaultRecruiterEmail =
    engagement.opportunity.job.organization.defaultRecruiter?.email;

  const recruiterEmail =
    assignedToEmail && assignedToEmail.length > 0
      ? assignedToEmail
      : defaultRecruiterEmail;

  if (!recruiterEmail) {
    console.error(
      `Recruiter email not found for ${engagement.id}, not sending email`,
    );
    return;
  }

  const firstName = engagement.opportunity.candidate.firstName;
  const lastName = engagement.opportunity.candidate.lastName;

  const job = {
    ...engagement.opportunity.job,
    companyName: getJobVariableValue(
      engagement.opportunity.job.variables,
      variableKeys.CLIENT_NAME,
    ),
  };

  const url = `/organizations/${engagement.opportunity.job.organizationId}/jobs/${engagement.opportunity.job.id}/opportunities/${engagement.opportunity.id}/overview`;

  await sendRecruiterEmailAction({
    url,
    firstName,
    lastName,
    recruiterEmail,
    job,
    scoreCard: await formatScoreCard(engagement.scoreCard as IScoreCard),
  });

  await db.engagement.update({
    where: { id: engagementId },
    data: {
      recruiterEmailSentAt: new Date(),
    },
  });
}

/**
 * Returns whether the required nodes in the call script were reached during this engagement.
 */
function hasReachedAllRequiredNodes(
  agentTaskEvents: EngagementAgentTaskEvent[],
  allScriptNodes: ScriptNode[],
): boolean {
  // Get all required nodes at the top level
  const requiredNodes = allScriptNodes.filter(
    (node) =>
      node.required &&
      node.requirementType === JobQualificationType.MANDATORY &&
      !node.conditionToEnter,
  );

  // If no required nodes, check if they reached the last node in the script
  if (requiredNodes.length === 0) {
    const lastNodeId = allScriptNodes[allScriptNodes.length - 1]?.id;
    return agentTaskEvents.some(
      (event) =>
        event.type === EngagementAgentTaskEventType.task_popped &&
        event.taskId === lastNodeId,
    );
  }

  // Get all completed task IDs
  const completedTaskIds = agentTaskEvents
    .filter((event) => event.type === EngagementAgentTaskEventType.task_popped)
    .map((event) => event.taskId);
  // Check if all required nodes have been completed
  return requiredNodes.every((node) => completedTaskIds.includes(node.id));
}

export async function getEngagementForRoom(roomName: string) {
  return db.engagement.findFirst({
    where: { roomName },
    select: {
      id: true,
    },
  });
}

export async function markEngagementComplete(engagementId: string) {
  return db.engagement.update({
    where: { id: engagementId },
    data: { completedAt: new Date() },
  });
}

export async function generateTranscriptSummary(engagementId: string) {
  const engagement = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
    select: {
      subStatus: true,
      messages: true,
      opportunity: {
        select: {
          job: {
            select: {
              organizationId: true,
              transcriptSummaryInstructions: true,
            },
          },
        },
      },
    },
  });

  if (!engagement.opportunity) {
    throw new Error(
      `Opportunity not found for engagement id: ${engagementId} while generating transcript summary`,
    );
  }

  const organizationId = engagement.opportunity.job.organizationId;

  if (
    engagement.subStatus !== CallSubStatus.completed &&
    engagement.subStatus !== CallSubStatus.partial
  ) {
    return null;
  }

  // Check for job-level instructions first, then fall back to organization-level
  const jobInstructions =
    engagement.opportunity.job.transcriptSummaryInstructions;

  let transcriptSummaryInstructions: string | null = jobInstructions;

  if (!transcriptSummaryInstructions) {
    const organization = await db.organization.findUniqueOrThrow({
      where: {
        id: organizationId,
      },
      select: {
        transcriptSummaryInstructions: true,
      },
    });

    transcriptSummaryInstructions = organization.transcriptSummaryInstructions;
  }

  if (!transcriptSummaryInstructions) {
    return null;
  }

  const { map } = messageIdMap([engagement]);
  const transcript = generateTranscriptForEngagement(
    // We don't include system messages because they are not part of the conversation
    // LLM takes "candidate hung up" system message as a sign that the candidate declined the job (which is incorrect)
    engagement.messages.filter((message) => message.role !== "system"),
    map,
  );

  const prompt = `${transcriptSummaryInstructions}

<transcript>
${transcript}
</transcript>
`;

  const existingSummary = await db.engagementTranscriptSummary.findUnique({
    where: { engagementId },
  });

  if (existingSummary?.prompt === prompt) {
    return existingSummary;
  }

  const result = await generateText({
    model: aiModel,
    prompt,
  });

  if (!result.text) {
    return null;
  }

  return await db.engagementTranscriptSummary.upsert({
    where: { engagementId },
    update: { summary: result.text, prompt },
    create: { engagementId, summary: result.text, prompt },
  });
}

export async function computeCallStatus(engagementId: string): Promise<{
  id: string;
  status: CallStatus;
  subStatus: CallSubStatus;
  durationSeconds: number;
  candidateDeclineReason: string | null;
} | null> {
  const engagement = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
    select: {
      id: true,
      roomName: true,
      createdAt: true,
      completedAt: true,
      candidateDeclineReason: true,
      scriptNodes: true,
      rescheduledAt: true,
      subStatus: true,
      opportunity: {
        select: {
          id: true,
          agentVersion: true,
          job: {
            select: { callScript: true, resumeCallsEnabled: true },
          },
          candidate: {
            select: { isBot: true },
          },
        },
      },
      messages: {
        orderBy: { createdAt: "asc" },
        select: {
          id: true,
          role: true,
          stateType: true,
          createdAt: true,
          content: true,
        },
      },
    },
  });

  if (!engagement.opportunity) {
    console.log(
      `No opportunity found for engagement ${engagementId} when computing call status`,
    );
    return null;
  }

  const callScript = engagement.opportunity.job.callScript;

  // Find all task events up to this point in time
  const takeMultiple =
    !engagement.opportunity.candidate.isBot &&
    engagement.opportunity.job.resumeCallsEnabled;

  const agentTaskEvents = takeMultiple
    ? await db.engagementAgentTaskEvent.findMany({
        where: {
          engagement: {
            OR: [
              {
                opportunityId: engagement.opportunity.id,
                createdAt: {
                  lte: engagement.createdAt,
                },
              },
              {
                id: engagement.id,
              },
            ],
          },
        },
        orderBy: { occurredAt: "asc" },
      })
    : await db.engagementAgentTaskEvent.findMany({
        where: {
          engagementId: engagement.id,
        },
        orderBy: { occurredAt: "asc" },
      });

  // If there are agent task events, ignore the script nodes (legacy logic)
  const allScriptNodes = parseScriptNodes(
    callScript as Prisma.JsonObject,
  ).nodes;

  const nonSystemMessages = engagement.messages.filter(
    (message) => message.role !== "system",
  );

  const userMessages = nonSystemMessages.filter(
    (message) => message.role === "user",
  );

  // Get the time user stays on the call
  // the duration between when the call started and when the user last spoke
  const lastUserMessage = userMessages[userMessages.length - 1];
  const interactiveDurationMs = lastUserMessage
    ? lastUserMessage.createdAt.getTime() - engagement.createdAt.getTime()
    : 0;

  const quickHangupThresholdMs = 1000 * 60; // 60 seconds

  const whoHangup: "agent" | "candidate" = engagement.messages.some(
    (message) =>
      message.role === "system" &&
      message.content
        .toUpperCase()
        .includes("CANDIDATE HAS BEEN SILENT FOR TOO LONG"),
  )
    ? "agent"
    : "candidate";

  let subStatus: CallSubStatus = (() => {
    if (engagement.candidateDeclineReason) {
      return CallSubStatus.candidate_declined;
    }

    // If the call doesn't have a completion time, it's still in progress
    if (!engagement.completedAt) {
      return CallSubStatus.in_progress;
    }

    if (engagement.rescheduledAt) {
      return CallSubStatus.rescheduled;
    }

    // If last node in the script was reached, it's a success
    const isCompleted = hasReachedAllRequiredNodes(
      agentTaskEvents,
      allScriptNodes,
    );
    if (isCompleted) {
      return CallSubStatus.completed;
    }

    // If there are no messages, assume the call was not answered
    if (userMessages.length < 1) {
      return CallSubStatus.no_answer;
    }
    const isOutbound = engagement.roomName?.startsWith("profileId:");

    // If voicemail script node or voicemail message is present, it's a voicemail
    if (isOutbound) {
      const foundVoicemailTask = agentTaskEvents.find(
        (event) =>
          event.engagementId === engagement.id && event.taskId === "voicemail",
      );
      const foundVoicemailMessage = engagement.messages.find(
        (message) =>
          message.role === "system" &&
          message.content.toUpperCase().includes("VOICEMAIL"),
      );

      if (foundVoicemailTask || foundVoicemailMessage) {
        return CallSubStatus.voicemail;
      }
    }

    // If the call ends very early (after 1 message or 60 seconds), it could be a quick hangup or a voicemail
    if (
      userMessages.length === 1 ||
      interactiveDurationMs < quickHangupThresholdMs
    ) {
      // If the phone ends early, and the agent hangup the call (not the candidate), assume it's a voicemail
      if (isOutbound && whoHangup === "agent") {
        return CallSubStatus.voicemail;
      }

      return CallSubStatus.quick_hangup;
    }

    return CallSubStatus.partial;
  })();

  const lastMessage = engagement.messages[engagement.messages.length - 1];
  let durationSeconds =
    lastMessage && subStatus !== CallSubStatus.in_progress
      ? (lastMessage.createdAt.getTime() - engagement.createdAt.getTime()) /
        1000
      : undefined;
  if (subStatus === CallSubStatus.no_answer) {
    durationSeconds = 0;
  }

  if (
    subStatus === CallSubStatus.partial ||
    subStatus === CallSubStatus.quick_hangup
  ) {
    const candidateDecline = await computeCandidateDecline(engagementId);
    if (candidateDecline.candidateDeclined) {
      subStatus = CallSubStatus.candidate_declined;
    } else {
      const rejection = await computeRejection(engagementId);
      if (rejection.rejected) {
        subStatus = CallSubStatus.rejected;
      }
    }
  }

  const updatedEngagement = await db.engagement.update({
    where: { id: engagementId },
    data: {
      status: getCallStatusFromSubstatus(subStatus),
      subStatus,
      durationSeconds,
      statusComputedAt: new Date(),
    },
    select: {
      id: true,
      status: true,
      subStatus: true,
      durationSeconds: true,
      candidateDeclineReason: true,
      rejectionReason: true,
    },
  });

  await computeOpportunityStatus(engagement.opportunity.id);

  await generateTranscriptSummary(engagementId);

  return updatedEngagement;
}

export const getAbandonedEngagements = async () => {
  const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
  const abandonedEngagements = await db.engagement.findMany({
    where: {
      createdAt: {
        lt: oneHourAgo,
      },
      completedAt: null,
      roomName: {
        not: null,
      },
      messages: {
        every: {
          createdAt: {
            lt: oneHourAgo,
          },
        },
      },
    },
    include: {
      messages: {
        orderBy: {
          createdAt: "desc",
        },
        take: 1,
      },
    },
  });
  return abandonedEngagements;
};

export const closeEngagement = async (engagementId: string) => {
  const engagement = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
  });
  if (engagement.roomName) {
    try {
      await deleteRoom(engagement.roomName);
    } catch (error) {
      if (!(error instanceof Error) || !error.message.includes("404")) {
        console.error(
          `Error deleting room ${engagement.roomName} for engagement ${engagement.id}`,
        );
      }
    }
    return await inngest.send({
      name: "livekit/room.finished",
      data: {
        roomName: engagement.roomName,
      },
    });
  }

  return await db.engagement.update({
    where: { id: engagementId },
    data: {
      completedAt: new Date(),
    },
  });
};

export const upsertEngagementScriptNodes = async (
  engagementId: string,
  newScriptNode: z.infer<typeof EngagementScriptNodeSchema>,
) => {
  const engagement = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
  });

  const oldScriptNodes = Array.isArray(engagement.scriptNodes)
    ? (engagement.scriptNodes as z.infer<typeof EngagementScriptNodeSchema>[])
    : [];

  // Update the script node if it already exists, otherwise add it
  const newScriptNodes = oldScriptNodes.map((scriptNode) => {
    if (scriptNode.id === newScriptNode.id) {
      return newScriptNode;
    }
    return scriptNode;
  });

  const found = newScriptNodes.find(
    (scriptNode) => scriptNode.id === newScriptNode.id,
  );
  if (!found) {
    newScriptNodes.push(newScriptNode);
  }

  return await db.engagement.update({
    where: { id: engagementId },
    data: {
      scriptNodes: newScriptNodes,
    },
  });
};

export const detectDoNotCallRequested = async (
  engagementId: string,
): Promise<z.infer<typeof doNotCallSchema>> => {
  const engagementWithMessages = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
    include: {
      messages: {
        orderBy: {
          createdAt: "asc",
        },
      },
    },
  });

  if (
    engagementWithMessages.messages.filter((message) => message.role === "user")
      .length === 0
  ) {
    return {
      doNotCall: false,
      reasoning: "No user messages found",
    };
  }

  // ensure this engagement had a conversation with the candidate that could have contained a do-not-call request:
  // The engagement state is not one of: voicemail, no-answer, success
  if (
    engagementWithMessages.subStatus === CallSubStatus.voicemail ||
    engagementWithMessages.subStatus === CallSubStatus.no_answer ||
    engagementWithMessages.subStatus === CallSubStatus.completed
  ) {
    return {
      doNotCall: false,
      reasoning: "Engagement state is not voicemail, no-answer, or success",
    };
  }
  // ensure the length of the audio is greater than 0
  if (engagementWithMessages.durationSeconds === 0) {
    return {
      doNotCall: false,
      reasoning: "Engagement duration is 0",
    };
  }

  const { map } = messageIdMap([engagementWithMessages]);
  const transcript = generateTranscriptForEngagement(
    engagementWithMessages.messages,
    map,
  );

  const result = await generateObject({
    model: aiModel,
    schema: doNotCallSchema,
    prompt: `**Instruction:**
Your goal is to determine whether, in the conversation below, the candidate explicitly requests **not** to be contacted again or to be removed from any call or contact lists. 

**Definition of an explicit do-not-call request:**
- Statements from the candidate such as "take me off your list," "don't call me again," "remove my number," "do not contact me,"  or any clear variant that directly indicates they wish to end all future contact.
- Clearly conveys that they want no further contact, even if it's not in those exact words. This may include:
  - Extreme rudeness or profanity directed at ending the call or dismissing the recruiter (e.g., "fuck off," "stop calling," "leave me alone," etc.).
  - Other language that unequivocally shows the candidate does not want to be contacted again.

**What does *not* count as an explicit do-not-call request?**
- An empty transcript is not an explicit do-not-call request.
- Voicemail is not an explicit do-not-call request.
- Saying "this isn't a good time," or "I have to go" is *not* an explicit do-not-call request.
- Declining the job or saying that they are not interested in the role is *not* an explicit do-not-call request.
- An empty transcript or a hangup that doesn't come with other evidence is *not* an explicit do-not-call request.

**Task:**
Read the transcript below and decide:
1. Reasoning for the decision of whether this is a do-not-call request, including a relevant quote from the transcript.
2. Whether the candidate explicitly requested to end all future contact (using phrases similar to the examples above)

Use the attached JSON schema to format your response.

**Transcript:**
${transcript}`,
  });

  return result.object;
};

const computeCandidateDecline = async (
  engagementId: string,
): Promise<{
  candidateDeclined: boolean;
  candidateDeclineReason: string | null;
}> => {
  const engagementWithMessages = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
    include: {
      messages: {
        orderBy: {
          createdAt: "asc",
        },
      },
    },
  });

  if (engagementWithMessages.candidateDeclineCheckedAt) {
    return {
      candidateDeclined: Boolean(engagementWithMessages.candidateDeclineReason),
      candidateDeclineReason: engagementWithMessages.candidateDeclineReason,
    };
  }

  const { map } = messageIdMap([engagementWithMessages]);
  const transcript = generateTranscriptForEngagement(
    // We don't include system messages because they are not part of the conversation
    // LLM takes "candidate hung up" system message as a sign that the candidate declined the job (which is incorrect)
    engagementWithMessages.messages.filter(
      (message) => message.role !== "system",
    ),
    map,
  );

  const result = await generateObject({
    model: aiModel,
    schema: z.object({
      // Put candidateDeclineReason before candidateDeclined to force LLM to reason first
      candidateDeclineReason: z
        .string()
        .nullable()
        .describe("The reason for the candidate decline"),
      candidateDeclined: z.boolean().describe("Whether the candidate declined"),
    }),
    prompt: `**Instruction:**
Based on the transcript below, determine if the candidate declined the job. If so, provide a reason for the decline.

Indicators that the candidate has declined the job:
- They explicitly express disinterest in the role (e.g., "I'm not interested").
- They say they are unavailable or not looking for a job.
- They request no further contact (e.g., "Take me off your list," "Don't call me again," "Remove my number," "Do not contact me").

Important Notes:
- If the recruiter rejects the candidate, it should NOT be considered a candidate decline.
- Do not assume the candidate declined the job if you don't have enough information.
- If the candidate requests to reschedule or be contacted later, it should NOT be considered a decline.

Use the attached JSON schema to format your response.

**Transcript:**
${transcript}`,
  });

  const { candidateDeclined, candidateDeclineReason } = result.object;

  // Computing the candidate decline reason is expensive, so we store the result in db to avoid recomputing it
  await db.engagement.update({
    where: { id: engagementId },
    data: {
      candidateDeclineCheckedAt: new Date(),
      candidateDeclineReason: candidateDeclined ? candidateDeclineReason : null,
    },
  });

  // Populate the opportunity with the candidate decline reason
  if (candidateDeclined) {
    if (engagementWithMessages.opportunityId) {
      await db.opportunity.update({
        where: { id: engagementWithMessages.opportunityId },
        data: {
          candidateDeclineReason,
        },
      });
    }
  }

  return {
    candidateDeclined,
    candidateDeclineReason,
  };
};

const computeRejection = async (
  engagementId: string,
): Promise<{
  rejected: boolean;
  rejectionReason: string | null;
}> => {
  const engagementWithMessages = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
    include: {
      messages: {
        orderBy: {
          createdAt: "asc",
        },
      },
    },
  });

  if (engagementWithMessages.rejectionCheckedAt) {
    return {
      rejected: Boolean(engagementWithMessages.rejectionReason),
      rejectionReason: engagementWithMessages.rejectionReason,
    };
  }

  const { map } = messageIdMap([engagementWithMessages]);
  const transcript = generateTranscriptForEngagement(
    // We don't include system messages because they are not part of the conversation
    // LLM takes "candidate hung up" system message as a sign that the candidate declined the job (which is incorrect)
    engagementWithMessages.messages.filter(
      (message) => message.role === "user" || message.role === "assistant",
    ),
    map,
  );

  const result = await generateObject({
    model: aiModel,
    schema: z.object({
      // Put rejectionReason before rejected to force LLM to reason first
      rejectionReason: z
        .string()
        .nullable()
        .describe("The reason for the rejection"),
      rejected: z.boolean().describe("Whether the candidate was rejected"),
    }),
    prompt: `**Instruction:**
Based on the transcript below, determine if the recruiter rejected the candidate. If so, provide a reason for the rejection.

Indicators that the recruiter rejected the candidate:
- They explicitly reject the candidate (e.g., "I don't think you're a good fit").

Important Notes:
- If the candidate declined the job, it should NOT be considered a rejection.
- Do not assume the candidate was rejected if you don't have enough information.

Use the attached JSON schema to format your response.

**Transcript:**
${transcript}`,
  });

  const { rejected, rejectionReason } = result.object;

  // Computing the candidate decline reason is expensive, so we store the result in db to avoid recomputing it
  await db.engagement.update({
    where: { id: engagementId },
    data: {
      rejectionCheckedAt: new Date(),
      rejectionReason: rejected ? rejectionReason : null,
    },
  });

  // Populate the opportunity with the rejection reason
  if (rejected) {
    if (engagementWithMessages.opportunityId) {
      await db.opportunity.update({
        where: { id: engagementWithMessages.opportunityId },
        data: {
          rejectionReason,
        },
      });
    }
  }

  return {
    rejected,
    rejectionReason,
  };
};

