   253→  // Get the opportunity with its candidate's phone number and any existing agent phone number
   254→  const opportunity = await db.opportunity.findUniqueOrThrow({
   255→    where: { id: opportunityId },
   256→    include: {
   257→      candidate: {
   258→        select: {
   259→          phoneNumber: true,
   260→        },
   261→      },
   262→      agentPhoneNumber: {
   263→        select: {
   264→          id: true,
   265→          number: true,
   266→          sipOutboundTrunkId: true,
   267→          sipOutboundTrunkForInboundId: true,
   268→        },
   269→      },
   270→    },
   271→  });
   272→
   273→  // If the opportunity already has an agent phone number, return it
   274→  if (opportunity.agentPhoneNumber) {
   275→    return opportunity.agentPhoneNumber;
   276→  }
   277→
   278→  // Get an agent phone number based on the candidate's phone number
   279→  const newAgentPhoneNumber = await getAgentPhoneNumber(
   280→    opportunity.candidate.phoneNumber || "",
   281→    organizationId,
   282→    envType,
