   394→export async function getAgentPhoneNumbers(
   395→  organizationId: string,
   396→  _period?: string,
   397→): Promise<AgentPhoneNumberWithEngagementCount[]> {
   398→  const period =
   399→    _period && ["all", "30d", "7d", "1d", "1h"].includes(_period)
   400→      ? _period
   401→      : "7d";
   402→
   403→  const periodFilter: Prisma.EngagementWhereInput = {};
   404→  switch (period) {
   405→    case "30d":
   406→      periodFilter.createdAt = {
   407→        gte: new Date(Date.now() - 1000 * 60 * 60 * 24 * 30),
   408→      };
   409→      break;
   410→    case "7d":
   411→      periodFilter.createdAt = {
   412→        gte: new Date(Date.now() - 1000 * 60 * 60 * 24 * 7),
   413→      };
   414→      break;
   415→    case "1d":
   416→      periodFilter.createdAt = {
   417→        gte: new Date(Date.now() - 1000 * 60 * 60 * 24),
   418→      };
   419→      break;
   420→    case "1h":
   421→      periodFilter.createdAt = {
   422→        gte: new Date(Date.now() - 1000 * 60 * 60),
   423→      };
   424→      break;
   425→    default:
   426→      break;
   427→  }
   428→
   429→  const agentPhoneNumbersWithEngagementsMadeInLast24HoursCount =
   430→    await db.agentPhoneNumber.findMany({
   431→      where: {
   432→        organizationId,
   433→      },
   434→      orderBy: {
   435→        number: "asc",
   436→      },
   437→      select: {
   438→        id: true,
   439→        number: true,
   440→        assignedAt: true,
   441→        organizationId: true,
   442→        defaultJob: {
   443→          select: {
   444→            id: true,
   445→            title: true,
   446→            variables: {
   447→              select: {
   448→                templateVariable: {
   449→                  select: {
   450→                    key: true,
   451→                  },
   452→                },
   453→                value: true,
   454→              },
   455→            },
   456→          },
   457→        },
   458→      },
   459→    });
   460→
   461→  const agentPhoneNumbersWithNoAnswerEngagementCount =
   462→    await db.agentPhoneNumber.findMany({
   463→      where: {
   464→        organizationId,
   465→      },
   466→      orderBy: {
   467→        number: "asc",
   468→      },
   469→      select: {
   470→        id: true,
   471→        // Count the number of outbound engagements created in the last 24 hours.
   472→        _count: {
   473→          select: {
   474→            engagements: {
   475→              where: {
   476→                subStatus: CallSubStatus.no_answer,
   477→                roomName: {
   478→                  startsWith: "profileId:",
   479→                },
   480→                ...periodFilter,
   481→              },
   482→            },
   483→          },
   484→        },
   485→      },
   486→    });
   487→
   488→  const agentPhoneNumbersWithVoicemailEngagementCount =
   489→    await db.agentPhoneNumber.findMany({
   490→      where: {
   491→        organizationId,
   492→      },
   493→      orderBy: {
   494→        number: "asc",
   495→      },
   496→      select: {
   497→        id: true,
   498→        // Count the number of outbound engagements created in the last 24 hours.
   499→        _count: {
   500→          select: {
   501→            engagements: {
   502→              where: {
   503→                subStatus: CallSubStatus.voicemail,
   504→                roomName: {
   505→                  startsWith: "profileId:",
   506→                },
   507→                ...periodFilter,
   508→              },
   509→            },
   510→          },
   511→        },
   512→      },
   513→    });
   514→
   515→  const agentPhoneNumbersWithInboundEngagementCount =
   516→    await db.agentPhoneNumber.findMany({
   517→      where: {
   518→        organizationId,
   519→      },
   520→      orderBy: {
   521→        number: "asc",
   522→      },
   523→      select: {
   524→        id: true,
   525→        // Count the number of outbound engagements created in the last 24 hours.
   526→        _count: {
   527→          select: {
   528→            engagements: {
   529→              where: {
   530→                OR: [
   531→                  {
   532→                    roomName: {
   533→                      startsWith: "call-",
   534→                    },
   535→                    ...periodFilter,
   536→                  },
   537→                  {
   538→                    roomName: {
   539→                      startsWith: "inbound:",
   540→                    },
   541→                    ...periodFilter,
   542→                  },
   543→                ],
   544→              },
   545→            },
   546→          },
   547→        },
   548→      },
   549→    });
   550→
   551→  const agentPhoneNumbersWithOutboundEngagementCount =
   552→    await db.agentPhoneNumber.findMany({
   553→      where: {
   554→        organizationId,
   555→      },
   556→      orderBy: {
   557→        number: "asc",
   558→      },
   559→      select: {
   560→        id: true,
   561→        // Count the number of outbound engagements created in the last 24 hours.
   562→        _count: {
   563→          select: {
   564→            engagements: {
   565→              where: {
   566→                roomName: {
   567→                  startsWith: "profileId:",
   568→                },
   569→                ...periodFilter,
   570→              },
   571→            },
   572→          },
   573→        },
   574→      },
   575→    });
   576→
   577→  return agentPhoneNumbersWithEngagementsMadeInLast24HoursCount.map(
   578→    (agentPhoneNumber): AgentPhoneNumberWithEngagementCount => ({
   579→      id: agentPhoneNumber.id,
   580→      number: agentPhoneNumber.number,
   581→      numberOfNoAnswerEngagements:
   582→        agentPhoneNumbersWithNoAnswerEngagementCount.find(
   583→          (a) => a.id === agentPhoneNumber.id,
   584→        )?._count.engagements ?? 0,
   585→      numberOfVoicemailEngagements:
   586→        agentPhoneNumbersWithVoicemailEngagementCount.find(
   587→          (a) => a.id === agentPhoneNumber.id,
   588→        )?._count.engagements ?? 0,
   589→      numberOfOutboundEngagements:
   590→        agentPhoneNumbersWithOutboundEngagementCount.find(
   591→          (a) => a.id === agentPhoneNumber.id,
   592→        )?._count.engagements ?? 0,
   593→      numberOfInboundEngagements:
   594→        agentPhoneNumbersWithInboundEngagementCount.find(
   595→          (a) => a.id === agentPhoneNumber.id,
   596→        )?._count.engagements ?? 0,
   597→      assignedAt: agentPhoneNumber.assignedAt,
   598→      defaultJob: agentPhoneNumber.defaultJob,
   599→      organizationId: agentPhoneNumber.organizationId,
   600→    }),
   601→  );
   602→}
