   604→export const orderTelnyxNumbers = async (
   605→  countryCode: CountryCode,
   606→  numbersToOrder: number,
   607→): Promise<{
   608→  orderedPhoneNumbers: string[];
   609→  error?: string;
   610→}> => {
   611→  if (numbersToOrder < 1) {
   612→    return {
   613→      orderedPhoneNumbers: [],
   614→      error: "Numbers to order must be greater than 0",
   615→    };
   616→  }
   617→
   618→  const features: ("sms" | "voice" | "hd_voice")[] = ["voice"];
   619→  const info = AGENT_PHONE_NUMBER_INFO[countryCode];
   620→  if (info.smsSupported) {
   621→    features.push("sms");
   622→  }
   623→  if (info.hdVoiceSupported) {
   624→    features.push("hd_voice");
   625→  }
   626→
   627→  const availableItems = await telnyx.availablePhoneNumbers.list({
   628→    "filter[features]": features,
   629→    "filter[country_code]": countryCode,
   630→    "filter[limit]": numbersToOrder,
   631→    "filter[phone_number_type]": info.numberType,
   632→  });
   633→
   634→  const availablePhoneNumbers = (availableItems.data || [])
   635→    .map((number) => number.phone_number || "")
   636→    .filter((phoneNumber) => Boolean(phoneNumber));
   637→
   638→  if (availablePhoneNumbers.length < numbersToOrder) {
   639→    return {
   640→      orderedPhoneNumbers: [],
   641→      error: "Not enough available numbers",
   642→    };
   643→  }
   644→
   645→  const numberOrder = await telnyx.numberOrders.create({
   646→    phone_numbers: availablePhoneNumbers.map((phoneNumber) => ({
   647→      phone_number: phoneNumber,
   648→    })),
   649→  });
   650→
   651→  if (numberOrder.data?.status === "failure") {
   652→    throw new Error("Failed to order phone numbers");
   653→  }
   654→
   655→  await db.agentPhoneNumber.createMany({
   656→    data: availablePhoneNumbers.map((phoneNumber) => ({
   657→      number: phoneNumber,
   658→      environment: "production",
   659→      countryCode,
   660→    })),
   661→  });
   662→
   663→  return {
   664→    orderedPhoneNumbers:
   665→      numberOrder.data?.phone_numbers?.map(
   666→        (number) => number.phone_number ?? "",
   667→      ) || [],
   668→  };
   669→};
