   741→export const getTelnyxCampaign = async (agentPhoneNumber: AgentPhoneNumber) => {
   742→  try {
   743→    const config = {
   744→      method: "get",
   745→      url: `https://api.telnyx.com/v2/10dlc/phone_number_campaigns/${agentPhoneNumber.number}`,
   746→      headers: {
   747→        Accept: "application/json",
   748→        Authorization: `Bearer ${env.TELNYX_API_KEY}`,
   749→      },
   750→    };
   751→
   752→    const response = await axios.request(config);
   753→    const parsedResponseData = z
   754→      .object({
   755→        campaignId: z.string(),
   756→        assignmentStatus: z.enum([
   757→          "FAILED_ASSIGNMENT",
   758→          "PENDING_ASSIGNMENT",
   759→          "ASSIGNED",
   760→          "PENDING_UNASSIGNMENT",
   761→          "FAILED_UNASSIGNMENT",
   762→        ]),
   763→      })
   764→      .parse(response.data);
   765→
   766→    return parsedResponseData;
   767→  } catch (err) {
   768→    if (err instanceof AxiosError && err.response?.status === 404) {
   769→      return null;
   770→    }
   771→
   772→    throw err;
   773→  }
   774→};
   775→
   776→export const setTelnyxCampaignId = async (
   777→  agentPhoneNumber: AgentPhoneNumber,
   778→  expectedCampaignId: string,
   779→) => {
   780→  const currentCampaign = await getTelnyxCampaign(agentPhoneNumber);
   781→
   782→  if (
   783→    !currentCampaign ||
   784→    currentCampaign.assignmentStatus === "FAILED_ASSIGNMENT" ||
   785→    currentCampaign.assignmentStatus === "FAILED_UNASSIGNMENT" ||
   786→    (currentCampaign.campaignId !== expectedCampaignId &&
   787→      currentCampaign.assignmentStatus !== "PENDING_ASSIGNMENT" &&
   788→      currentCampaign.assignmentStatus !== "PENDING_UNASSIGNMENT")
   789→  ) {
   790→    // If the campaign ID is already set, we have to unassign it first
   791→    if (currentCampaign?.campaignId) {
   792→      await axios.request({
   793→        method: "delete",
   794→        maxBodyLength: Infinity,
   795→        url: `https://api.telnyx.com/v2/10dlc/phone_number_campaigns/${agentPhoneNumber.number}`,
   796→        headers: {
   797→          Accept: "application/json",
   798→          Authorization: `Bearer ${env.TELNYX_API_KEY}`,
   799→        },
   800→      });
   801→    } else {
   802→      // It's not possible to create new campaign immediately after unassigning
   803→      // So for each cron run of the function, we only either assign or unassign
   804→      const data = JSON.stringify({
   805→        phoneNumber: agentPhoneNumber.number,
   806→        campaignId: expectedCampaignId,
   807→      });
   808→
   809→      await axios.request({
   810→        method: "post",
   811→        url: "https://api.telnyx.com/v2/10dlc/phone_number_campaigns",
   812→        headers: {
   813→          "Content-Type": "application/json",
   814→          "Accept": "application/json",
   815→          "Authorization": `Bearer ${env.TELNYX_API_KEY}`,
   816→        },
   817→        data: data,
   818→      });
   819→    }
   820→  }
   821→
   822→  // Check if the campaign is assigned
   823→  const updatedCampaign = await getTelnyxCampaign(agentPhoneNumber);
   824→  if (updatedCampaign?.campaignId === expectedCampaignId) {
   825→    await db.agentPhoneNumber.update({
   826→      where: { id: agentPhoneNumber.id },
   827→      data: {
   828→        telnyxCampaignId: updatedCampaign.campaignId,
   829→        telnyxCampaignAssignmentStatus: updatedCampaign.assignmentStatus,
   830→      },
   831→    });
   832→  }
   833→
   834→  return {
   835→    number: agentPhoneNumber.number,
   836→    ...updatedCampaign,
   837→  };
   838→};
