   869→        cnam_listing_enabled: true,
   870→        cnam_listing_details: cnamListingName,
   871→      },
   872→
   873→      // Default, but required by the Telnyx API
   874→      tech_prefix_enabled: false,
   875→      caller_id_name_enabled: false,
   876→      usage_payment_method: "pay-per-minute",
   877→      inbound_call_screening: "disabled",
   878→    },
   879→  );
   880→
   881→  const cnamListingEnabled = response.data?.cnam_listing?.cnam_listing_enabled;
   882→  const updatedCnamListingName =
