   886→    throw new Error("Failed to configure Telnyx phone number CNAM listing.");
   887→  }
   888→
   889→  return db.agentPhoneNumber.update({
   890→    where: { id: agentPhoneNumber.id },
   891→    data: { telnyxCnamListingName: updatedCnamListingName },
