"use server";

import { SIPTransport } from "@livekit/protocol";
import axios, { AxiosError } from "axios";
import { PhoneNumber, parsePhoneNumberFromString } from "libphonenumber-js";
import { SipClient } from "livekit-server-sdk";
import Telnyx from "telnyx";
import { z } from "zod";

import {
  type AgentPhoneNumber,
  CallSubStatus,
  type Prisma,
} from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";

import {
  AGENT_PHONE_NUMBER_INFO,
  CountryCode,
  DAILY_OUTBOUND_CALL_LIMIT_PER_AGENT_PHONE_NUMBER,
  MAX_US_AGENT_PHONE_NUMBERS_PER_ORGANIZATION,
  TELNYX_MESSAGING_PROFILE_ID,
  TELNYX_SIP_CONNECTION_ID,
} from "@/common/libs/agent-phone-number-constants";
import { env } from "@/env";

const telnyx = new Telnyx(env.TELNYX_API_KEY);

const getInboundSipClient = () => {
  return new SipClient(
    env.LIVEKIT_URL_INBOUND,
    env.LIVEKIT_API_KEY_INBOUND,
    env.LIVEKIT_API_SECRET_INBOUND,
  );
};

const getOutboundSipClient = () => {
  return new SipClient(
    env.LIVEKIT_URL,
    env.LIVEKIT_API_KEY,
    env.LIVEKIT_API_SECRET,
  );
};

const assignAgentPhoneNumberToOrganization = async (
  organizationId: string,
  countryCode: string,
) => {
  if (countryCode === CountryCode.US.toString()) {
    // Check if the organization has reached the maximum number of US agent phone numbers.
    const usAgentPhoneNumbers = await db.agentPhoneNumber.count({
      where: {
        organizationId,
        countryCode: CountryCode.US,
      },
    });
    if (usAgentPhoneNumbers >= MAX_US_AGENT_PHONE_NUMBERS_PER_ORGANIZATION) {
      return null;
    }
  }

  const where: Prisma.AgentPhoneNumberWhereInput = {
    organizationId: null,
    countryCode,
    environment: "production",
    // Only assign a number if it has an inbound and outbound trunk and dispatch rule
    sipInboundTrunkId: {
      not: null,
    },
    sipOutboundTrunkId: {
      not: null,
    },
    sipOutboundTrunkForInboundId: {
      not: null,
    },
    sipInboundDispatchRuleId: {
      not: null,
    },
    // Only assign a number if it has a SIP connection
    telnyxPhoneNumberId: {
      not: null,
    },
    telnyxSipConnectionId: {
      not: null,
    },
  };

  const assignedAgentPhoneNumber = await db.agentPhoneNumber.findFirst({
    where,
  });

  if (!assignedAgentPhoneNumber) {
    return null;
  }

  await db.agentPhoneNumber.update({
    where: { id: assignedAgentPhoneNumber.id },
    data: { organizationId, assignedAt: new Date() },
  });

  return assignedAgentPhoneNumber;
};

const getOrganizationAvailableAgentPhoneNumber = async (
  organizationId: string,
  countryCode: CountryCode,
  environment?: string,
): Promise<{
  id: string;
  number: string;
  sipOutboundTrunkId: string | null;
  sipOutboundTrunkForInboundId: string | null;
}> => {
  const agentPhoneNumbers = await db.agentPhoneNumber.findMany({
    where: {
      organizationId,
      countryCode,
      ...(environment ? { environment } : {}),
    },
    select: {
      id: true,
      number: true,
      sipOutboundTrunkId: true,
      sipOutboundTrunkForInboundId: true,
      // Count the number of outbound engagements created in the last 24 hours.
      _count: {
        select: {
          engagements: {
            where: {
              createdAt: {
                gte: new Date(Date.now() - 1000 * 60 * 60 * 24), // Engagement created in the last 24 hours
              },
              roomName: {
                startsWith: "profileId:",
              },
            },
          },
        },
      },
    },
  });

  // Sort by the number of outbound engagements in the last 24 hours (ascending)
  agentPhoneNumbers.sort((a, b) => {
    return a._count.engagements - b._count.engagements;
  });

  const leastDailyUsedAgentPhoneNumber = agentPhoneNumbers[0];

  let foundAgentPhoneNumber = leastDailyUsedAgentPhoneNumber
    ? {
        id: leastDailyUsedAgentPhoneNumber.id,
        number: leastDailyUsedAgentPhoneNumber.number,
        sipOutboundTrunkId: leastDailyUsedAgentPhoneNumber.sipOutboundTrunkId,
        sipOutboundTrunkForInboundId:
          leastDailyUsedAgentPhoneNumber.sipOutboundTrunkForInboundId,
      }
    : null;

  // If the number has been used for more than the daily limit,
  // attempt to assign a new number to the organization.
  // If no new number is available, return the number that has been used the least in the last 24 hours.
  if (
    !leastDailyUsedAgentPhoneNumber ||
    leastDailyUsedAgentPhoneNumber._count.engagements >=
      DAILY_OUTBOUND_CALL_LIMIT_PER_AGENT_PHONE_NUMBER
  ) {
    const assignedAgentPhoneNumber = await assignAgentPhoneNumberToOrganization(
      organizationId,
      countryCode,
    );
    if (assignedAgentPhoneNumber) {
      foundAgentPhoneNumber = {
        id: assignedAgentPhoneNumber.id,
        number: assignedAgentPhoneNumber.number,
        sipOutboundTrunkId: assignedAgentPhoneNumber.sipOutboundTrunkId,
        sipOutboundTrunkForInboundId:
          assignedAgentPhoneNumber.sipOutboundTrunkForInboundId,
      };
    }
  }

  if (!foundAgentPhoneNumber) {
    // If we can't find a number for the country code, try to find a US number.
    if (countryCode !== CountryCode.US) {
      return getOrganizationAvailableAgentPhoneNumber(
        organizationId,
        CountryCode.US,
        environment,
      );
    }

    // If we can't find a US number, throw an error.
    throw new Error(
      `No agent phone numbers found for countryCode: ${countryCode}`,
    );
  }

  return foundAgentPhoneNumber;
};

export const getAgentPhoneNumber = async (
  toNumber: string,
  organizationId: string,
  envType?: string,
): Promise<{
  id: string;
  number: string;
  sipOutboundTrunkId: string | null;
  sipOutboundTrunkForInboundId: string | null;
}> => {
  // Parse the phone number to get the country code
  let parsedPhoneNumber: PhoneNumber | undefined;
  try {
    if (toNumber) {
      parsedPhoneNumber = parsePhoneNumberFromString(toNumber);
    }
  } catch (error) {
    console.error("Error parsing phone number", error);
  }

  let countryCode = "US";
  if (parsedPhoneNumber?.country) {
    countryCode = parsedPhoneNumber.country;
  } else if (toNumber) {
    console.warn(`Can't identify country code for phone number ${toNumber}`);
  }

  // If we have a number for the country code in the pool, use it. Otherwise, use US number.
  let agentPhoneNumberCountryCode = CountryCode.US;
  if (Object.keys(AGENT_PHONE_NUMBER_INFO).includes(countryCode)) {
    agentPhoneNumberCountryCode = countryCode as CountryCode;
  }

  // Find a new agent phone number for the organization
  return await getOrganizationAvailableAgentPhoneNumber(
    organizationId,
    agentPhoneNumberCountryCode,
    envType,
  );
};

export const getOpportunityAgentPhoneNumber = async (
  opportunityId: string,
  organizationId: string,
  envType?: string,
): Promise<{
  id: string;
  number: string;
  sipOutboundTrunkId: string | null;
  sipOutboundTrunkForInboundId: string | null;
}> => {
  // Get the opportunity with its candidate's phone number and any existing agent phone number
  const opportunity = await db.opportunity.findUniqueOrThrow({
    where: { id: opportunityId },
    include: {
      candidate: {
        select: {
          phoneNumber: true,
        },
      },
      agentPhoneNumber: {
        select: {
          id: true,
          number: true,
          sipOutboundTrunkId: true,
          sipOutboundTrunkForInboundId: true,
        },
      },
    },
  });

  // If the opportunity already has an agent phone number, return it
  if (opportunity.agentPhoneNumber) {
    return opportunity.agentPhoneNumber;
  }

  // Get an agent phone number based on the candidate's phone number
  const newAgentPhoneNumber = await getAgentPhoneNumber(
    opportunity.candidate.phoneNumber || "",
    organizationId,
    envType,
  );

  // Assign the retrieved number to the opportunity
  await db.opportunity.update({
    where: { id: opportunityId },
    data: { agentPhoneNumberId: newAgentPhoneNumber.id },
  });

  return newAgentPhoneNumber;
};

export const getEngagementAgentPhoneNumber = async (
  engagementId: string,
  envType?: string,
): Promise<{
  id: string;
  number: string;
  sipOutboundTrunkId: string | null;
  sipOutboundTrunkForInboundId: string | null;
}> => {
  const engagement = await db.engagement.findUniqueOrThrow({
    where: { id: engagementId },
    include: {
      agentPhoneNumber: {
        select: {
          id: true,
          number: true,
          sipOutboundTrunkId: true,
          sipOutboundTrunkForInboundId: true,
        },
      },
      opportunity: {
        select: {
          id: true,
          job: {
            select: {
              id: true,
              organizationId: true,
            },
          },
        },
      },
    },
  });

  // If the engagement already has an agent phone number, return it
  if (engagement.agentPhoneNumber) {
    return engagement.agentPhoneNumber;
  }

  if (!engagement.opportunityId) {
    throw new Error(
      `Opportunity ID not found in getEngagementAgentPhoneNumber for engagementId ${engagementId}`,
    );
  }

  if (!engagement.opportunity) {
    throw new Error(
      `Opportunity not found in getEngagementAgentPhoneNumber for engagementId ${engagementId}`,
    );
  }

  const { opportunity } = engagement;
  const organizationId = opportunity.job.organizationId;
  if (!organizationId) {
    throw new Error(
      `Organization ID not found in getEngagementAgentPhoneNumber for engagementId ${engagementId}, opportunityId ${opportunity.id}, and jobId ${opportunity.job.id}`,
    );
  }

  // Get or assign an agent phone number for the opportunity
  const agentPhoneNumber = await getOpportunityAgentPhoneNumber(
    opportunity.id,
    organizationId,
    envType,
  );

  // Assign the agent phone number to the engagement
  await db.engagement.update({
    where: {
      id: engagementId,
    },
    data: {
      agentPhoneNumberId: agentPhoneNumber.id,
    },
  });

  return agentPhoneNumber;
};

export interface AgentPhoneNumberWithEngagementCount {
  id: string;
  number: string;
  numberOfNoAnswerEngagements: number;
  numberOfVoicemailEngagements: number;
  numberOfOutboundEngagements: number;
  numberOfInboundEngagements: number;
  assignedAt: Date | null;
  organizationId: string | null;
  defaultJob: {
    id: string;
    title: string;
    variables: {
      templateVariable: {
        key: string;
      };
      value: string;
    }[];
  } | null;
}

export async function getAgentPhoneNumbers(
  organizationId: string,
  _period?: string,
): Promise<AgentPhoneNumberWithEngagementCount[]> {
  const period =
    _period && ["all", "30d", "7d", "1d", "1h"].includes(_period)
      ? _period
      : "7d";

  const periodFilter: Prisma.EngagementWhereInput = {};
  switch (period) {
    case "30d":
      periodFilter.createdAt = {
        gte: new Date(Date.now() - 1000 * 60 * 60 * 24 * 30),
      };
      break;
    case "7d":
      periodFilter.createdAt = {
        gte: new Date(Date.now() - 1000 * 60 * 60 * 24 * 7),
      };
      break;
    case "1d":
      periodFilter.createdAt = {
        gte: new Date(Date.now() - 1000 * 60 * 60 * 24),
      };
      break;
    case "1h":
      periodFilter.createdAt = {
        gte: new Date(Date.now() - 1000 * 60 * 60),
      };
      break;
    default:
      break;
  }

  const agentPhoneNumbersWithEngagementsMadeInLast24HoursCount =
    await db.agentPhoneNumber.findMany({
      where: {
        organizationId,
      },
      orderBy: {
        number: "asc",
      },
      select: {
        id: true,
        number: true,
        assignedAt: true,
        organizationId: true,
        defaultJob: {
          select: {
            id: true,
            title: true,
            variables: {
              select: {
                templateVariable: {
                  select: {
                    key: true,
                  },
                },
                value: true,
              },
            },
          },
        },
      },
    });

  const agentPhoneNumbersWithNoAnswerEngagementCount =
    await db.agentPhoneNumber.findMany({
      where: {
        organizationId,
      },
      orderBy: {
        number: "asc",
      },
      select: {
        id: true,
        // Count the number of outbound engagements created in the last 24 hours.
        _count: {
          select: {
            engagements: {
              where: {
                subStatus: CallSubStatus.no_answer,
                roomName: {
                  startsWith: "profileId:",
                },
                ...periodFilter,
              },
            },
          },
        },
      },
    });

  const agentPhoneNumbersWithVoicemailEngagementCount =
    await db.agentPhoneNumber.findMany({
      where: {
        organizationId,
      },
      orderBy: {
        number: "asc",
      },
      select: {
        id: true,
        // Count the number of outbound engagements created in the last 24 hours.
        _count: {
          select: {
            engagements: {
              where: {
                subStatus: CallSubStatus.voicemail,
                roomName: {
                  startsWith: "profileId:",
                },
                ...periodFilter,
              },
            },
          },
        },
      },
    });

  const agentPhoneNumbersWithInboundEngagementCount =
    await db.agentPhoneNumber.findMany({
      where: {
        organizationId,
      },
      orderBy: {
        number: "asc",
      },
      select: {
        id: true,
        // Count the number of outbound engagements created in the last 24 hours.
        _count: {
          select: {
            engagements: {
              where: {
                OR: [
                  {
                    roomName: {
                      startsWith: "call-",
                    },
                    ...periodFilter,
                  },
                  {
                    roomName: {
                      startsWith: "inbound:",
                    },
                    ...periodFilter,
                  },
                ],
              },
            },
          },
        },
      },
    });

  const agentPhoneNumbersWithOutboundEngagementCount =
    await db.agentPhoneNumber.findMany({
      where: {
        organizationId,
      },
      orderBy: {
        number: "asc",
      },
      select: {
        id: true,
        // Count the number of outbound engagements created in the last 24 hours.
        _count: {
          select: {
            engagements: {
              where: {
                roomName: {
                  startsWith: "profileId:",
                },
                ...periodFilter,
              },
            },
          },
        },
      },
    });

  return agentPhoneNumbersWithEngagementsMadeInLast24HoursCount.map(
    (agentPhoneNumber): AgentPhoneNumberWithEngagementCount => ({
      id: agentPhoneNumber.id,
      number: agentPhoneNumber.number,
      numberOfNoAnswerEngagements:
        agentPhoneNumbersWithNoAnswerEngagementCount.find(
          (a) => a.id === agentPhoneNumber.id,
        )?._count.engagements ?? 0,
      numberOfVoicemailEngagements:
        agentPhoneNumbersWithVoicemailEngagementCount.find(
          (a) => a.id === agentPhoneNumber.id,
        )?._count.engagements ?? 0,
      numberOfOutboundEngagements:
        agentPhoneNumbersWithOutboundEngagementCount.find(
          (a) => a.id === agentPhoneNumber.id,
        )?._count.engagements ?? 0,
      numberOfInboundEngagements:
        agentPhoneNumbersWithInboundEngagementCount.find(
          (a) => a.id === agentPhoneNumber.id,
        )?._count.engagements ?? 0,
      assignedAt: agentPhoneNumber.assignedAt,
      defaultJob: agentPhoneNumber.defaultJob,
      organizationId: agentPhoneNumber.organizationId,
    }),
  );
}

export const orderTelnyxNumbers = async (
  countryCode: CountryCode,
  numbersToOrder: number,
): Promise<{
  orderedPhoneNumbers: string[];
  error?: string;
}> => {
  if (numbersToOrder < 1) {
    return {
      orderedPhoneNumbers: [],
      error: "Numbers to order must be greater than 0",
    };
  }

  const features: ("sms" | "voice" | "hd_voice")[] = ["voice"];
  const info = AGENT_PHONE_NUMBER_INFO[countryCode];
  if (info.smsSupported) {
    features.push("sms");
  }
  if (info.hdVoiceSupported) {
    features.push("hd_voice");
  }

  const availableItems = await telnyx.availablePhoneNumbers.list({
    "filter[features]": features,
    "filter[country_code]": countryCode,
    "filter[limit]": numbersToOrder,
    "filter[phone_number_type]": info.numberType,
  });

  const availablePhoneNumbers = (availableItems.data || [])
    .map((number) => number.phone_number || "")
    .filter((phoneNumber) => Boolean(phoneNumber));

  if (availablePhoneNumbers.length < numbersToOrder) {
    return {
      orderedPhoneNumbers: [],
      error: "Not enough available numbers",
    };
  }

  const numberOrder = await telnyx.numberOrders.create({
    phone_numbers: availablePhoneNumbers.map((phoneNumber) => ({
      phone_number: phoneNumber,
    })),
  });

  if (numberOrder.data?.status === "failure") {
    throw new Error("Failed to order phone numbers");
  }

  await db.agentPhoneNumber.createMany({
    data: availablePhoneNumbers.map((phoneNumber) => ({
      number: phoneNumber,
      environment: "production",
      countryCode,
    })),
  });

  return {
    orderedPhoneNumbers:
      numberOrder.data?.phone_numbers?.map(
        (number) => number.phone_number ?? "",
      ) || [],
  };
};

