export const getTelnyxCampaign = async (agentPhoneNumber: AgentPhoneNumber) => {
  try {
    const config = {
      method: "get",
      url: `https://api.telnyx.com/v2/10dlc/phone_number_campaigns/${agentPhoneNumber.number}`,
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${env.TELNYX_API_KEY}`,
      },
    };

    const response = await axios.request(config);
    const parsedResponseData = z
      .object({
        campaignId: z.string(),
        assignmentStatus: z.enum([
          "FAILED_ASSIGNMENT",
          "PENDING_ASSIGNMENT",
          "ASSIGNED",
          "PENDING_UNASSIGNMENT",
          "FAILED_UNASSIGNMENT",
        ]),
      })
      .parse(response.data);

    return parsedResponseData;
  } catch (err) {
    if (err instanceof AxiosError && err.response?.status === 404) {
      return null;
    }

    throw err;
  }
};

export const setTelnyxCampaignId = async (
  agentPhoneNumber: AgentPhoneNumber,
  expectedCampaignId: string,
) => {
  const currentCampaign = await getTelnyxCampaign(agentPhoneNumber);

  if (
    !currentCampaign ||
    currentCampaign.assignmentStatus === "FAILED_ASSIGNMENT" ||
    currentCampaign.assignmentStatus === "FAILED_UNASSIGNMENT" ||
    (currentCampaign.campaignId !== expectedCampaignId &&
      currentCampaign.assignmentStatus !== "PENDING_ASSIGNMENT" &&
      currentCampaign.assignmentStatus !== "PENDING_UNASSIGNMENT")
  ) {
    // If the campaign ID is already set, we have to unassign it first
    if (currentCampaign?.campaignId) {
      await axios.request({
        method: "delete",
        maxBodyLength: Infinity,
        url: `https://api.telnyx.com/v2/10dlc/phone_number_campaigns/${agentPhoneNumber.number}`,
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${env.TELNYX_API_KEY}`,
        },
      });
    } else {
      // It's not possible to create new campaign immediately after unassigning
      // So for each cron run of the function, we only either assign or unassign
      const data = JSON.stringify({
        phoneNumber: agentPhoneNumber.number,
        campaignId: expectedCampaignId,
      });

      await axios.request({
        method: "post",
        url: "https://api.telnyx.com/v2/10dlc/phone_number_campaigns",
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json",
          "Authorization": `Bearer ${env.TELNYX_API_KEY}`,
        },
        data: data,
      });
    }
  }

  // Check if the campaign is assigned
  const updatedCampaign = await getTelnyxCampaign(agentPhoneNumber);
  if (updatedCampaign?.campaignId === expectedCampaignId) {
    await db.agentPhoneNumber.update({
      where: { id: agentPhoneNumber.id },
      data: {
        telnyxCampaignId: updatedCampaign.campaignId,
        telnyxCampaignAssignmentStatus: updatedCampaign.assignmentStatus,
      },
    });
  }

  return {
    number: agentPhoneNumber.number,
    ...updatedCampaign,
  };
};

export const setTelnyxCnameListing = async (
  agentPhoneNumber: AgentPhoneNumber,
) => {
  const { telnyxPhoneNumberId } = agentPhoneNumber;
  if (!telnyxPhoneNumberId) {
    throw new Error("Agent phone number has no Telnyx phone number ID.");
  }

  if (!agentPhoneNumber.organizationId) {
    throw new Error("Agent phone number has no organization ID.");
  }

  const { agentCallerId } = await db.organization.findUniqueOrThrow({
    where: { id: agentPhoneNumber.organizationId },
    select: { agentCallerId: true },
  });

  const cnamListingName: string =
    agentCallerId && agentCallerId.length > 0 ? agentCallerId : "Recruiter";

  // If the details are already set, do nothing
  if (cnamListingName === agentPhoneNumber.telnyxCnamListingName) {
    return agentPhoneNumber;
  }

  const response = await telnyx.phoneNumbers.updateVoiceSettings(
    telnyxPhoneNumberId,
    {
      cnam_listing: {
        cnam_listing_enabled: true,
        cnam_listing_details: cnamListingName,
      },

      // Default, but required by the Telnyx API
      tech_prefix_enabled: false,
      caller_id_name_enabled: false,
      usage_payment_method: "pay-per-minute",
      inbound_call_screening: "disabled",
    },
  );

  const cnamListingEnabled = response.data?.cnam_listing?.cnam_listing_enabled;
  const updatedCnamListingName =
    response.data?.cnam_listing?.cnam_listing_details;

  if (!cnamListingEnabled || updatedCnamListingName !== cnamListingName) {
    throw new Error("Failed to configure Telnyx phone number CNAM listing.");
  }

  return db.agentPhoneNumber.update({
    where: { id: agentPhoneNumber.id },
    data: { telnyxCnamListingName: updatedCnamListingName },
  });
};

export const setTelnyxHdVoiceSetting = async (
  agentPhoneNumber: AgentPhoneNumber,
) => {
  const { telnyxPhoneNumberId } = agentPhoneNumber;
  if (!telnyxPhoneNumberId) {
    throw new Error("Agent phone number has no Telnyx phone number ID.");
  }

  let telnyxHdVoice = false;

  try {
    const response = await telnyx.phoneNumbers.update(telnyxPhoneNumberId, {
      hd_voice_enabled: true,
    });
    telnyxHdVoice = Boolean(response.data);
  } catch (err) {
    if (
      // err instanceof Telnyx.errors.TelnyxInvalidRequestError &&
      (
        err as { raw: { errors: { detail: string }[] } }
      ).raw.errors[0]?.detail.includes("This number does not support HD Voice")
    ) {
      telnyxHdVoice = false;
    } else {
      throw err;
    }
  }

  return db.agentPhoneNumber.update({
    where: { id: agentPhoneNumber.id },
    data: {
      telnyxHdVoice,
    },
  });
};

export const createOutboundTrunk = async (
  agentPhoneNumber: AgentPhoneNumber,
) => {
  const outboundSipClient = getOutboundSipClient();
  const outboundTrunks = await outboundSipClient.listSipOutboundTrunk();
  const outboundTrunk = outboundTrunks.find((outboundTrunk) =>
    outboundTrunk.numbers.includes(agentPhoneNumber.number),
  );
  if (outboundTrunk) {
    return outboundTrunk;
  }

  const newOutboundTrunk = await outboundSipClient.createSipOutboundTrunk(
    `outbound-trunk-${agentPhoneNumber.number}`,
    "sip.telnyx.com",
    [agentPhoneNumber.number],
    {
      transport: SIPTransport.SIP_TRANSPORT_AUTO,
      auth_username: env.TELNYX_OUTBOUND_TRUNK_USERNAME,
      auth_password: env.TELNYX_OUTBOUND_TRUNK_PASSWORD,
    },
  );
  return newOutboundTrunk;
};

