export const createInboundDispatchRule = async (
  agentPhoneNumber: AgentPhoneNumber,
) => {
  const sipInboundTrunkId = agentPhoneNumber.sipInboundTrunkId;
  if (!sipInboundTrunkId) {
    throw new Error("Agent phone number has no inbound trunk");
  }

  const inboundSipClient = getInboundSipClient();

  const dispatchRules = await inboundSipClient.listSipDispatchRule();
  const dispatchRule = dispatchRules.find((dispatchRule) =>
    dispatchRule.trunkIds.includes(sipInboundTrunkId),
  );

  if (dispatchRule) {
    return dispatchRule;
  }

  return inboundSipClient.createSipDispatchRule(
    {
      type: "individual",
      roomPrefix: `inbound:${agentPhoneNumber.number}`,
      pin: "",
    },
    {
      trunkIds: [sipInboundTrunkId],
      hidePhoneNumber: false,
    },
  );
};

