import { CallSubStatus } from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";

import { JobSource } from "@/common/models/jobs";
import { SALARY_CONFIRMATION_TRIGGER } from "@/common/models/notification-templates";
import { stages } from "@/common/models/stages";
import { inngest } from "@/server/inngest/client";
import { handleException } from "@/server/inngest/utils";
import { updateAshbyCandidateForEngagement } from "@/server/libs/ats/ashby";
import { setCandidateDoNotCall } from "@/server/libs/candidates";
import {
  computeCallStatus,
  detectDoNotCallRequested,
  generateScoreCardForOpportunityEngagement,
  sendRecruiterEmail,
} from "@/server/libs/engagements";
import { sendNotificationsForTrigger } from "@/server/libs/notification-templates";
import { computeOpportunityRequirementCounts } from "@/server/libs/opportunities";
import {
  sendEngagementSuccessMessage,
  sendSlackAlert,
} from "@/server/libs/slack";
import { changeStage, moveOpportunityToNextStage } from "@/server/libs/stages";

export const processEngagementResultsFunction = inngest.createFunction(
  { id: "process-engagement-results" },
  { event: "purplefish/engagement.completed" },
  async ({ event, step }) => {
    const { engagementId } = event.data;

    const engagement = await db.engagement.findUnique({
      where: { id: engagementId },
      select: {
        opportunity: {
          select: {
            id: true,
            job: { select: { organizationId: true } },
            candidate: {
              select: {
                id: true,
                phoneNumber: true,
                firstName: true,
                lastName: true,
                doNotCall: true,
              },
            },
          },
        },
      },
    });

    if (!engagement) {
      throw new Error(
        `Engagement not found for id: ${engagementId} while processing engagement results`,
      );
    }

    await step.run("generate-score-card-for-opportunity", async () => {
      try {
        await generateScoreCardForOpportunityEngagement(engagementId);
      } catch (error) {
        handleException(error);
        throw error;
      }
    });

    await step.run("update-call-status", async () => {
      const status = await computeCallStatus(engagementId);
      return status
        ? {
            engagementId: engagementId,
            status: status.status,
            subStatus: status.subStatus,
          }
        : null;
    });

    await step.run("update-opportunity-requirement-counts", async () => {
      if (!engagement.opportunity) {
        return {
          opportunityId: null,
          mandatoryRequirementCount: 0,
          unmetMandatoryRequirementCount: 0,
          metMandatoryRequirementCount: 0,
          noDataMandatoryRequirementCount: 0,
          metPreferredRequirementCount: 0,
        };
      }

      const {
        mandatoryRequirementCount,
        unmetMandatoryRequirementCount,
        metMandatoryRequirementCount,
        noDataMandatoryRequirementCount,
        metPreferredRequirementCount,
      } = await computeOpportunityRequirementCounts(engagement.opportunity.id);
      await db.opportunity.update({
        where: { id: engagement.opportunity.id },
        data: {
          mandatoryRequirementCount,
          unmetMandatoryRequirementCount,
          metMandatoryRequirementCount,
          noDataMandatoryRequirementCount,
          metPreferredRequirementCount,
        },
      });
      return {
        opportunityId: engagement.opportunity.id,
        mandatoryRequirementCount,
        unmetMandatoryRequirementCount,
        metMandatoryRequirementCount,
        noDataMandatoryRequirementCount,
        metPreferredRequirementCount,
      };
    });

    await step.run("detect-do-not-call-requested", async () => {
      try {
        if (!engagement.opportunity) {
          throw new Error(
            `Opportunity or candidate not found for engagement id: ${engagementId} while processing engagement results`,
          );
        }

        const doNotCallRequested = await detectDoNotCallRequested(engagementId);
        if (doNotCallRequested.doNotCall) {
          console.log(
            `Do not call request detected for opportunity ${engagement.opportunity.id}: ${doNotCallRequested.reasoning}`,
          );
          await setCandidateDoNotCall({
            organizationId: engagement.opportunity.job.organizationId,
            candidateId: engagement.opportunity.candidate.id,
            userId: null,
            doNotCall: true,
            reason: "Candidate was marked as do not call by system",
          });
        }
        return doNotCallRequested;
      } catch (error) {
        handleException(error);
        throw error;
      }
    });

    await inngest.send({
      name: "purplefish/engagement.processed",
      data: {
        engagementId,
      },
    });
  },
);

export const checkSystemMessagesForEngagementFunction = inngest.createFunction(
  { id: "check-system-messages-for-engagement" },
  { event: "purplefish/engagement.completed" },
  async ({ event, step }) => {
    const { engagementId } = event.data;

    const engagement = await db.engagement.findUnique({
      where: { id: engagementId },
      select: {
        messages: true,
        opportunity: {
          select: {
            id: true,
            job: {
              select: {
                title: true,
                organizationId: true,
                id: true,
              },
            },
            candidate: {
              select: {
                id: true,
                firstName: true,
                lastName: true,
              },
            },
          },
        },
      },
    });

    if (!engagement) {
      throw new Error(
        `Engagement not found for id: ${engagementId} while checking for system messages`,
      );
    }

    if (!engagement.opportunity) {
      throw new Error(
        `Opportunity not found for engagement id: ${engagementId} while checking for system messages`,
      );
    }

    const firstName = engagement.opportunity.candidate.firstName;
    const lastName = engagement.opportunity.candidate.lastName;
    const jobTitle = engagement.opportunity.job.title;
    const organizationId = engagement.opportunity.job.organizationId;

    await step.run("check-system-messages", async () => {
      try {
        if (engagement.messages.length === 0) {
          return engagement;
        }
        const hasSystemMessage = engagement.messages.some(
          (message) => message.role === "system",
        );
        if (!hasSystemMessage) {
          console.error(
            `No system messages found in engagement ${engagementId}`,
          );
          if (engagement.opportunity) {
            await sendSlackAlert(
              `:warning: Technical Issue: No system messages found in engagement ${engagementId} \nCandidate: ${firstName} ${lastName}\nJob: ${jobTitle}\n\n<https://app.purplefish.com/organizations/${organizationId}/jobs/${engagement.opportunity.job.id}/opportunities/${engagement.opportunity.id}/overview>`,
            );
          }
        }
        return engagement;
      } catch (error) {
        if (error instanceof Error) {
          handleException(error);
          throw error;
        }
        throw new Error("Unknown error checking system messages");
      }
    });
  },
);

// TODO: move the ASHBY update to a sync file in inngest/ashby
export const updateAtsForEngagementFunction = inngest.createFunction(
  { id: "update-ats-for-engagement" },
  { event: "purplefish/engagement.processed" },
  async ({ event, step }) => {
    const { engagementId } = event.data;

    const engagement = await step.run(
      "find-engagement",
      async () =>
        await db.engagement.findUnique({
          where: { id: engagementId },
          select: {
            opportunity: {
              select: {
                id: true,
                job: { select: { source: true, organizationId: true } },
                atsId: true,
                status: true,
              },
            },
          },
        }),
    );

    if (!engagement) {
      throw new Error(
        `Engagement not found for id: ${engagementId} while updating ATS`,
      );
    }

    await step.run("update-ats", async () => {
      if (!engagement.opportunity) {
        throw new Error(
          `Opportunity not found for engagement id: ${engagementId} while updating ATS`,
        );
      }
      const jobSource = engagement.opportunity.job.source;

      // Legacy handlers for integrations not yet migrated to the new pattern
      if (jobSource === JobSource.ATS_SMART_RECRUITERS.toString()) {
        await inngest.send({
          name: "smart-recruiters/update-candidate.triggered",
          data: { engagementId },
        });
        return true;
      }

      if (jobSource === JobSource.ATS_SALESFORCE.toString()) {
        await inngest.send({
          name: "salesforce/update-candidate.triggered",
          data: { engagementId },
        });
        return true;
      }

      if (jobSource === JobSource.ATS_TEMPWORKS.toString()) {
        await inngest.send({
          name: "tempworks/update-candidate.triggered",
          data: { engagementId },
        });
        return true;
      }

      if (jobSource === JobSource.ATS_ASHBY.toString()) {
        if (!engagement.opportunity.atsId) {
          throw new Error(
            `ATS ID not found for engagement id: ${engagementId} while updating Ashby`,
          );
        }
        await updateAshbyCandidateForEngagement({
          engagementId,
          organizationId: engagement.opportunity.job.organizationId,
          atsId: engagement.opportunity.atsId,
        });
        return true;
      }
      return false;
    });
  },
);

export const sendNotificationsForEngagementFunction = inngest.createFunction(
  { id: "send-notifications-for-engagement" },
  [
    { event: "purplefish/engagement.processed" },
    { event: "purplefish/followup.triggered" },
  ],
  async ({ event, step }) => {
    const { engagementId } = event.data;

    const engagement = await db.engagement.findUnique({
      where: { id: engagementId },
      select: {
        subStatus: true,
        salaryRequirementCents: true,
        opportunityId: true,
      },
    });

    if (!engagement) {
      throw new Error(`Engagement not found for id: ${engagementId}`);
    }

    await step.run("send-followups", async () => {
      if (!engagement.opportunityId) {
        console.log(
          `No opportunity found for engagement ${engagementId}, skipping notifications`,
        );
        return;
      }
      try {
        if (
          engagement.salaryRequirementCents !== null &&
          engagement.salaryRequirementCents > 0
        ) {
          await sendNotificationsForTrigger({
            opportunityId: engagement.opportunityId,
            engagementId: engagementId,
            trigger: SALARY_CONFIRMATION_TRIGGER,
          });
        }
        if (engagement.subStatus === CallSubStatus.completed) {
          // For now this is not in the notification templates
          await sendRecruiterEmail(engagementId);
          await sendEngagementSuccessMessage(engagementId);
        }

        await sendNotificationsForTrigger({
          opportunityId: engagement.opportunityId,
          engagementId: engagementId,
          trigger: engagement.subStatus,
        });
      } catch (error) {
        handleException(error);
        throw error;
      }
    });
  },
);

// Phone screen specific logic to move the opportunity to the next stage
// If certain clients want different outcomes for statuses, we'll need to move the mappings to the stage configuration level
export const moveOpportunityToNextStageFunction = inngest.createFunction(
  { id: "move-opportunity-to-next-stage" },
  { event: "purplefish/engagement.processed" },
  async ({ event, step }) => {
    const { engagementId } = event.data;

    const engagement = await db.engagement.findUnique({
      where: { id: engagementId },
      include: {
        opportunity: {
          select: {
            id: true,
            status: true,
            currentStageId: true,
            job: {
              select: {
                organizationId: true,
              },
            },
          },
        },
      },
    });

    if (!engagement) {
      throw new Error(`Engagement not found for id: ${engagementId}`);
    }

    await step.run("move-opportunity-to-next-stage", async () => {
      try {
        if (!engagement.opportunity) {
          throw new Error(
            `Opportunity not found for engagement id: ${engagementId} in moveOpportunityToNextStageFunction`,
          );
        }

        const nextStageId = await moveOpportunityToNextStage({
          opportunityId: engagement.opportunity.id,
        });

        return {
          nextStageId,
          opportunityStatus: engagement.opportunity.status,
        };
      } catch (error) {
        handleException(error);
        throw error;
      }
    });
  },
);

export const moveCandidateToPhoneScreenFunction = inngest.createFunction(
  { id: "move-candidate-to-phone-screen" },
  { event: "purplefish/engagement.created" },
  async ({ event, step }) => {
    const { engagementId } = event.data;

    const engagement = await db.engagement.findUnique({
      where: { id: engagementId },
      select: {
        roomName: true,
        opportunity: {
          select: {
            id: true,
            currentStageId: true,
            job: {
              select: {
                organizationId: true,
              },
            },
          },
        },
      },
    });

    if (!engagement) {
      throw new Error(`Engagement not found for id: ${engagementId}`);
    }

    if (!engagement.opportunity) {
      throw new Error(
        `Opportunity not found for engagement id: ${engagementId} in moveCandidateToPhoneScreenFunction`,
      );
    }

    await step.run("move-candidate-to-phone-screen", async () => {
      const opportunity = engagement.opportunity!;

      // Check if candidate is already in PHONE_SCREEN stage
      if (opportunity.currentStageId === stages.PHONE_SCREEN) {
        return { alreadyInPhoneScreen: true };
      }

      // Move candidate to PHONE_SCREEN stage
      const reason = `Moved to phone screen stage due to engagement created${
        engagement.roomName ? ` for room: ${engagement.roomName}` : ""
      }`;

      await changeStage({
        organizationId: opportunity.job.organizationId,
        opportunityId: opportunity.id,
        currentStageId: opportunity.currentStageId,
        nextStageId: stages.PHONE_SCREEN,
        userId: null,
        reason,
      });

      return {
        movedToPhoneScreen: true,
        reason,
        roomName: engagement.roomName,
      };
    });
  },
);

