import { NextResponse } from "next/server";

import z from "zod";

import { db } from "@purplefish-ai/db/server";

import { checkApiRequestAuth } from "@/common/libs/check-api-request-auth";
import {
  FAKE_AGENT_PHONE_NUMBER_ID,
  FAKE_ENGAGEMENT_ID,
  FAKE_OPPORTUNITY_ID,
} from "@/common/models/demo-fake-ids";
import { JobStatus } from "@/common/models/jobs";
import { env } from "@/env";
import { getEngagementAgentPhoneNumber } from "@/server/libs/agent-phone-numbers";
import { upsertEngagement } from "@/server/libs/engagements";

const UpsertEngagementSchema = z.object({
  profileId: z.string().optional(),
  roomName: z.string(),

  // New fields
  opportunityId: z.string().optional(),
  candidatePhoneNumber: z.string().optional(),
  agentPhoneNumber: z.string().optional(),
});

async function getOpportunityForPhoneNumbers(
  agentPhoneNumber: string,
  candidatePhoneNumber: string,
): Promise<string | undefined> {
  // Try to find an opportunity with these phone numbers
  const opportunity = await db.opportunity.findFirst({
    where: {
      agentPhoneNumber: {
        number: agentPhoneNumber,
      },
      candidate: {
        phoneNumber: candidatePhoneNumber,
      },
      job: {
        status: {
          in: [JobStatus.ACTIVE, JobStatus.PAUSED],
        },
      },
    },
    orderBy: {
      createdAt: "desc",
    },
    select: {
      id: true,
    },
  });

  return opportunity?.id;
}

export async function POST(request: Request) {
  try {
    checkApiRequestAuth(request, env.AGENT_AUTH_TOKEN_SECRET);

    const body: unknown = await request.json();
    const validationResult = UpsertEngagementSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        { error: validationResult.error.message },
        { status: 400 },
      );
    }
    const roomName = validationResult.data.roomName;

    // TODO update the agent to use opportunityId
    let opportunityId =
      validationResult.data.opportunityId || validationResult.data.profileId;

    if (!opportunityId) {
      if (
        validationResult.data.agentPhoneNumber &&
        validationResult.data.candidatePhoneNumber
      ) {
        opportunityId = await getOpportunityForPhoneNumbers(
          validationResult.data.agentPhoneNumber,
          validationResult.data.candidatePhoneNumber,
        );
      }
    }

    if (!opportunityId) {
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400 },
      );
    }

    if (opportunityId === FAKE_OPPORTUNITY_ID) {
      return NextResponse.json(
        {
          id: FAKE_ENGAGEMENT_ID,
          createdAt: new Date(),
          updatedAt: new Date(),
          profileId: FAKE_OPPORTUNITY_ID,
          roomName: roomName,
          agentPhoneNumber: {
            id: FAKE_AGENT_PHONE_NUMBER_ID,
            number: "+11234567890",
            sipOutboundTrunkId: null,
            sipOutboundTrunkForInboundId: null,
          },
          isNewlyCreated: true, // indicates if the engagement was created or already existed
        },
        { status: 201 },
      );
    }

    const { candidateId } = await db.opportunity.findUniqueOrThrow({
      where: { id: opportunityId },
      select: {
        candidateId: true,
      },
    });

    const newEngagement = await upsertEngagement({
      opportunityId,
      roomName,
      candidateId,
    });
    const agentPhoneNumber = await getEngagementAgentPhoneNumber(
      newEngagement.id,
    );

    return NextResponse.json(
      {
        id: newEngagement.id,
        createdAt: newEngagement.createdAt,
        updatedAt: newEngagement.updatedAt,
        profileId: newEngagement.opportunityId,
        roomName: newEngagement.roomName,
        agentPhoneNumber,
        isNewlyCreated: newEngagement.isNewlyCreated, // indicates if the engagement was created or already existed
      },
      { status: newEngagement.isNewlyCreated ? 201 : 200 },
    );
  } catch (error) {
    console.error("Error creating engagement:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

