import { parsePhoneNumberFromString } from "libphonenumber-js";

export function parseInboundRoomName(
  roomName: string,
): { agentNumber: string | null; candidateNumber: string } | null {
  if (!roomName.startsWith("inbound:")) {
    return null;
  }
  // Room name will look like: inbound:+12192553215_6303921551_asdf

  const parts = roomName.split(":");
  if (parts.length !== 2) {
    return null;
  }

  const [prefix, rest] = parts;
  if (prefix !== "inbound") {
    return null;
  }
  if (!rest) {
    return null;
  }

  const restParts = rest.split("_");
  if (restParts.length !== 3) {
    return null;
  }

  const [agentRaw, candidateRaw] = restParts;

  if (!agentRaw || !candidateRaw) {
    return null;
  }

  try {
    // Agent number is always in format +(country code)(number)
    const parsedAgentNumber = parsePhoneNumberFromString(agentRaw);
    // Candidate number can be in local format (without +) if candidate and agent are in the same country,
    // or in format +(country code)(number) if they are in different countries
    const parsedCandidateNumber = candidateRaw.startsWith("+")
      ? parsePhoneNumberFromString(candidateRaw)
      : parsePhoneNumberFromString(
          candidateRaw,
          parsedAgentNumber?.country ?? "US",
        );

    const agentNumber = parsedAgentNumber?.number;
    const candidateNumber = parsedCandidateNumber?.number;

    if (!candidateNumber) {
      throw new Error(`Invalid candidate number: ${candidateRaw}`);
    }

    return {
      agentNumber: agentNumber ?? null,
      candidateNumber,
    };
  } catch (error) {
    console.error("Error parsing inbound room name", { error, roomName });
    return null;
  }
}

