import axios, { type AxiosInstance, type AxiosRequestConfig } from "axios";

import type * as generatedApi from "./generated";
import type {
  MessageReceivedAgentsMessagesReceivedPostResponses,
  ScheduleEventAgentsScheduleEventPostResponses,
} from "./generated";

// Define the configuration type
export interface MessagingAgentsClientConfig {
  baseUrl: string;
  apiKey: string;
}

// Client class to handle API requests with authentication
export class MessagingAgentsClient {
  private client: AxiosInstance;
  private config: MessagingAgentsClientConfig;

  constructor(config: MessagingAgentsClientConfig) {
    this.config = config;

    // Create an axios instance with default configuration
    this.client = axios.create({
      baseURL: config.baseUrl,
      headers: {
        "Content-Type": "application/json",
        "X-API-Key": config.apiKey,
      },
    });
  }

  // schedule an event
  async scheduleEvent(
    params: generatedApi.ScheduleEventAgentsScheduleEventPostData,
  ): Promise<ScheduleEventAgentsScheduleEventPostResponses> {
    const response = await this.client.post(
      "/agents/schedule_event",
      params.body,
    );
    return response.data;
  }

  // Health check endpoint
  async healthCheck() {
    const response = await this.client.get("/health");
    return response.data;
  }

  // Handle an incoming message
  async messageReceived(
    params: generatedApi.MessageReceivedAgentsMessagesReceivedPostData,
  ): Promise<MessageReceivedAgentsMessagesReceivedPostResponses> {
    const response = await this.client.post(
      "/agents/messages/received",
      params.body,
    );
    return response.data;
  }

  // Get participant availability
  async getParticipantAvailability(
    params: generatedApi.GetParticipantAvailabilityAgentsGetParticipantAvailabilityPostData,
  ) {
    const response = await this.client.post(
      "/agents/get_participant_availability",
      params.body,
    );
    return response.data;
  }

  // Mark an agent as complete
  async agentComplete(
    agentId: string,
    params: Omit<
      generatedApi.AgentCompleteAgentsAgentIdCompletePostData,
      "agent_id"
    >,
  ) {
    const url = `/agents/${agentId}/complete`;
    const response = await this.client.post(url, params.body);
    return response.data;
  }

  // Generic request method for custom endpoints
  async request<T>(config: AxiosRequestConfig): Promise<T> {
    const response = await this.client.request<T>(config);
    return response.data;
  }
}

// Create a singleton instance with environment variables
let clientInstance: MessagingAgentsClient | null = null;

export function getMessagingAgentsClient(
  config?: Partial<MessagingAgentsClientConfig>,
) {
  if (!clientInstance || config) {
    if (
      !process.env.MESSAGING_AGENTS_API_URL ||
      !process.env.MESSAGING_AGENTS_API_KEY
    ) {
      console.warn(process.env.MESSAGING_AGENTS_API_URL);
      console.warn(process.env.MESSAGING_AGENTS_API_KEY);
      console.warn(
        "Could not instantiate the messaging agents client - required API keys not provided.",
      );
      return null;
    }

    const baseConfig = {
      baseUrl: process.env.MESSAGING_AGENTS_API_URL,
      apiKey: process.env.MESSAGING_AGENTS_API_KEY,
    };

    clientInstance = new MessagingAgentsClient({
      ...baseConfig,
      ...config,
    });
  }

  return clientInstance;
}

// Export a default instance for easy import
export const messagingAgentsApi = getMessagingAgentsClient();

// Re-export generated types and functions
export * from "./generated";

