export async function getOpportunityLastInProgressScriptNodeId(
  opportunityId: string,
  isBot: boolean,
  resumeCallsEnabled: boolean,
  scriptNodes: ScriptNode[],
) {
  if (isBot || !resumeCallsEnabled) {
    // Treat every engagement as new.
    return null;
  }

  // Filter to only top level nodes.
  scriptNodes = scriptNodes.filter((node) => !node.conditionToEnter);

  // Find all the tasks we popped.
  const completedEvents = await db.engagementAgentTaskEvent.findMany({
    where: {
      engagement: {
        opportunityId,
      },
      type: EngagementAgentTaskEventType.task_popped,
    },
  });

  // If we didn't pop any tasks, resume from the very beginning.
  if (completedEvents.length === 0) {
    return null;
  }

  // Otherwise, find the _first_ node we didn't pop.
  for (const scriptNode of scriptNodes) {
    const completedEvent = completedEvents.find(
      (event) => event.taskId === scriptNode.id,
    );
    if (!completedEvent) {
      return scriptNode.id;
    }
  }

  // If we popped everything, just resume from the very end so the agent says something.
  return scriptNodes[scriptNodes.length - 1]?.id || null;
}

