/**
 * Checks if a sequence has completed and handles the opportunity status accordingly.
 * A sequence is considered complete when all items are either triggered or cancelled.
 *
 * @param opportunityId - The ID of the opportunity to check
 * @param lastProcessedItemId - The ID of the sequence item that was just processed
 * @returns true if the sequence was marked as ended, false otherwise
 */
export const checkAndHandleSequenceCompletion = async ({
  opportunityId,
  lastProcessedItemId,
}: {
  opportunityId: string;
  lastProcessedItemId: string;
}): Promise<boolean> => {
  // Get all sequence items for this opportunity
  // Order by scheduledAt to get them in sequence order
  const sequenceItems = await db.opportunitySequenceItem.findMany({
    where: { opportunityId },
    orderBy: { scheduledAt: "asc" },
  });

  if (sequenceItems.length === 0) {
    return false;
  }

  // Check if all items are either triggered or cancelled
  const allItemsProcessed = sequenceItems.every(
    (item) => item.triggeredAt !== null || item.cancelledAt !== null,
  );

  if (!allItemsProcessed) {
    return false;
  }

  // Find the last sequence item that was just processed
  const lastProcessedItem = sequenceItems.find(
    (item) => item.id === lastProcessedItemId,
  );

  if (!lastProcessedItem) {
    return false;
  }

  // Get the last item in the sequence by order
  const lastSequenceItem = sequenceItems[sequenceItems.length - 1];
  if (!lastSequenceItem) {
    return false;
  }
  const isLastItem = lastProcessedItem.id === lastSequenceItem.id;

  // Determine if we should end the sequence based on the rules:
  // 1. If it's the last item and it's email/SMS, end immediately
  // 2. If it's the last item and it's phone that was cancelled (missing number), end immediately
  // 3. If all items are processed but last item was phone with number, let engagement handle it
  const shouldEndSequence =
    isLastItem &&
    (lastProcessedItem.channel === "email" ||
      lastProcessedItem.channel === "sms" ||
      lastProcessedItem.cancelledAt !== null);

  // Also end sequence if all items are cancelled (no successful outreach)
  const allItemsCancelled = sequenceItems.every(
    (item) => item.cancelledAt !== null,
  );

  if (shouldEndSequence || allItemsCancelled) {
    // Get the opportunity with job info for organization context
    const opportunity = await db.opportunity.findUnique({
      where: { id: opportunityId },
      select: {
        status: true,
        job: {
          select: {
            organizationId: true,
          },
        },
      },
    });

    if (!opportunity) {
      return false;
    }

    // Only update if not already in a terminal state
    if (
      opportunity.status !== OpportunityStatus.sequence_ended &&
      opportunity.status !== OpportunityStatus.completed &&
      opportunity.status !== OpportunityStatus.candidate_declined
    ) {
      console.log(
        `Marking opportunity ${opportunityId} as sequence_ended after processing last item ${lastProcessedItemId}`,
      );

      await updateOpportunity({
        organizationId: opportunity.job.organizationId,
        opportunityId,
        data: {
          status: OpportunityStatus.sequence_ended,
        },
      });

      // Trigger the stage transition which will archive the opportunity
      await moveOpportunityToNextStage({ opportunityId });

      return true;
    }
  }

  return false;
};

