import { type NextRequest, NextResponse } from "next/server";

import { type WebhookEvent, WebhookReceiver } from "livekit-server-sdk";
import { z } from "zod";

import { env } from "@/env";
import { inngest } from "@/server/inngest/client";
import { logLiveKitEvent } from "@/server/libs/livekit";

export async function POST(request: NextRequest) {
  let event: WebhookEvent | null = null;
  try {
    const type = z
      .enum(["inbound", "outbound"])
      .parse(request.nextUrl.searchParams.get("type") || "outbound");

    const receiver = new WebhookReceiver(
      type === "inbound" ? env.LIVEKIT_API_KEY_INBOUND : env.LIVEKIT_API_KEY,
      type === "inbound"
        ? env.LIVEKIT_API_SECRET_INBOUND
        : env.LIVEKIT_API_SECRET,
    );

    event = await receiver.receive(
      await request.text(),
      request.headers.get("Authorization") ?? "",
    );
  } catch (error) {
    console.error("Error receiving webhook:", error);
    return NextResponse.json({ success: false }, { status: 403 });
  }
  if (event.event === "room_finished") {
    if (!event.room?.sid) {
      console.error("Room SID is null");
      return NextResponse.json({ success: false }, { status: 400 });
    }
    console.log(`Sending room finished event for room ${event.room.name}`);
    const result = await inngest.send({
      name: "livekit/room.finished",
      id: `${event.room.sid}-room-finished`,
      data: {
        roomName: event.room.name,
      },
    });
    console.log(`Room finished event sent: ${JSON.stringify(result)}`);
  }
  await logLiveKitEvent(event);
  return NextResponse.json({ success: true });
}

